  base64_map['i'] = 34; base64_map['j'] = 35; base64_map['k'] = 36; base64_map['l'] = 37;
  base64_map['m'] = 38; base64_map['n'] = 39; base64_map['o'] = 40; base64_map['p'] = 41;
