rcutils_ret_t rcutils_decode_base64(
  const char * base64_str,
  rcutils_uint8_array_t * byte_array,
  const rcutils_allocator_t * allocator)
{
#ifdef _WIN32
  InitOnceExecuteOnce(
    &base64_map_initialization_once,
    initialize_base64_map_callback,
    NULL,
    NULL);
#else
  pthread_once(&base64_map_initialization_once, initialize_base64_map);
#endif

  RCUTILS_CHECK_ARGUMENT_FOR_NULL(base64_str, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(byte_array, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    allocator, "base64 decode function has no valid allocator",
    return RCUTILS_RET_INVALID_ARGUMENT);

  // Check that byte_array is zero-initialized
  if (byte_array->buffer != NULL ||
    byte_array->buffer_length != 0 ||
    byte_array->buffer_capacity != 0)
  {
    RCUTILS_SET_ERROR_MSG("byte_array must be zero-initialized before decoding");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }

  size_t input_str_len = rcutils_strnlen(base64_str, RCUTILS_BASE64_ENCODED_MAX_LENGTH);
  if (RCUTILS_BASE64_ENCODED_MAX_LENGTH == input_str_len) {
    RCUTILS_SET_ERROR_MSG("base64 string length exceeds limit");
    return RCUTILS_RET_ERROR;
  }
  if (0 == input_str_len) {
    return RCUTILS_RET_OK;
  }
  if (0 != (input_str_len % 4)) {
    RCUTILS_SET_ERROR_MSG("base64 string length is not a multiple of 4");
    return RCUTILS_RET_ERROR;
  }

  // Count padding characters ('=' at the end)
  // Valid base64 can have 0, 1, or 2 padding characters
  size_t padding = 0;
  if ('=' == base64_str[input_str_len - 1]) {
    padding++;
    if (input_str_len >= 2 && '=' == base64_str[input_str_len - 2]) {
      padding++;
    }
  }

  if (padding > 2) {
    RCUTILS_SET_ERROR_MSG("invalid base64 padding");
    return RCUTILS_RET_ERROR;
  }

  // Calculate the decoded output size
  // Each 4-character block decodes to 3 bytes, minus any padding
  size_t decoded_len_blocks = input_str_len / 4;
  size_t max_decoded_len = decoded_len_blocks * 3;

  if (padding >= max_decoded_len) {
    RCUTILS_SET_ERROR_MSG("invalid base64: padding exceeds expected length");
    return RCUTILS_RET_ERROR;
  }

  size_t decoded_len = max_decoded_len - padding;

  // Allocate memory for the decoded output
  rcutils_ret_t ret = rcutils_uint8_array_init(byte_array, decoded_len, allocator);
  if (ret != RCUTILS_RET_OK) {
    return ret;
  }
  byte_array->buffer_length = decoded_len;

  // Decode the base64 string block by block
  // Each iteration processes 4 input characters (sextets) to produce 3 output bytes (octets)
  size_t write_index = 0;
  for (size_t read_index = 0; read_index < input_str_len; read_index += 4) {
    // Extract 4 sextets (6-bit values) from the input
    uint8_t sextets[4] = {0, 0, 0, 0};

    for (size_t i = 0; i < 4; ++i) {
      char c = base64_str[read_index + i];

      if ('=' == c) {
        // Padding character validation:
        // - Must be in the last block (last 2 positions of the string)
        // - If at position 2, position 3 must also be padding
        // - Cannot appear at positions 0 or 1 of a block
        if ((read_index + i) < (input_str_len - 2) || i < 2) {
          RCUTILS_SET_ERROR_MSG("invalid base64 padding position");
          goto err;
        }

        if (i == 2 && base64_str[read_index + 3] != '=') {
          RCUTILS_SET_ERROR_MSG("invalid base64 padding");
          goto err;
        }

        sextets[i] = 0;
      } else {
        // Map base64 character to its 6-bit value
        uint8_t value = base64_map[(uint8_t)c];
        if (BASE64_INVALID == value) {
          RCUTILS_SET_ERROR_MSG("invalid base64 character");
          goto err;
        }
        sextets[i] = value;
      }
    }

    // Combine the 4 sextets (6 bits each) into a 24-bit block
    // Sextet 0: bits 23-18 | Sextet 1: bits 17-12 | Sextet 2: bits 11-6 | Sextet 3: bits 5-0
    uint32_t block =
      ((uint32_t)sextets[0] << 18) |
      ((uint32_t)sextets[1] << 12) |
      ((uint32_t)sextets[2] << 6) |
      ((uint32_t)sextets[3] << 0);

    // Extract 3 bytes from the 24-bit block
    // Byte 0: bits 23-16 | Byte 1: bits 15-8 | Byte 2: bits 7-0
    if (write_index < decoded_len) {
      byte_array->buffer[write_index++] = (uint8_t)((block >> 16) & 0xFFu);
    }
    if (write_index < decoded_len) {
      byte_array->buffer[write_index++] = (uint8_t)((block >> 8) & 0xFFu);
    }
    if (write_index < decoded_len) {
      byte_array->buffer[write_index++] = (uint8_t)(block & 0xFFu);
    }
  }

  return RCUTILS_RET_OK;

err:
  // Clean up allocated memory on error
  if (RCUTILS_RET_OK != rcutils_uint8_array_fini(byte_array)) {
    RCUTILS_SET_ERROR_MSG("failed to finalize byte_array during cleanup");
  }
  return RCUTILS_RET_ERROR;
}

rcutils_ret_t rcutils_encode_base64(
  const rcutils_uint8_array_t * byte_array,
  char ** base64_str,
  const rcutils_allocator_t * allocator)
{
  // Base64 encoding table
  static const char base64_chars[] =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

  RCUTILS_CHECK_ARGUMENT_FOR_NULL(byte_array, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(byte_array->buffer, RCUTILS_RET_INVALID_ARGUMENT);
  if (byte_array->buffer_length == 0) {
    RCUTILS_SET_ERROR_MSG("byte_array length is zero");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(base64_str, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    allocator, "base64 encode function has no valid allocator",
    return RCUTILS_RET_INVALID_ARGUMENT);

  *base64_str = NULL;

  // Check for input size limit to prevent integer overflow
  // The maximum input size should ensure the encoded output fits within reasonable limits
  // Base64 encoding: 3 bytes -> 4 chars, so max input = (LIMIT / 4) * 3
  size_t max_input_len = (RCUTILS_BASE64_ENCODED_MAX_LENGTH / 4) * 3;
  if (byte_array->buffer_length > max_input_len) {
    RCUTILS_SET_ERROR_MSG("byte_array length exceeds limit for base64 encoding");
    return RCUTILS_RET_ERROR;
  }

  // Calculate the encoded output size
  // Each 3-byte block encodes to 4 characters, plus padding if necessary
  size_t full_blocks = byte_array->buffer_length / 3;
  size_t remainder = byte_array->buffer_length % 3;
  size_t encoded_len = full_blocks * 4;

  // Add padding block if there's a remainder
  if (remainder > 0) {
    encoded_len += 4;
  }

  // Allocate memory for the encoded output (plus null terminator)
  *base64_str = (char *)allocator->allocate(encoded_len + 1, allocator->state);
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    *base64_str,
    "failed to allocate memory for base64 encode",
    return RCUTILS_RET_BAD_ALLOC);

  // Encode the byte array block by block
  // Each iteration processes 3 input bytes (octets) to produce 4 output characters (sextets)
  size_t read_index = 0;
  size_t write_index = 0;

  // Process full 3-byte blocks
  while (read_index + 3 <= byte_array->buffer_length) {
    // Combine 3 bytes (octets) into a 24-bit block
    // Byte 0: bits 23-16 | Byte 1: bits 15-8 | Byte 2: bits 7-0
    uint32_t block =
      ((uint32_t)byte_array->buffer[read_index] << 16) |
      ((uint32_t)byte_array->buffer[read_index + 1] << 8) |
      ((uint32_t)byte_array->buffer[read_index + 2]);

    // Extract 4 sextets (6-bit values) from the 24-bit block
    // Sextet 0: bits 23-18 | Sextet 1: bits 17-12 | Sextet 2: bits 11-6 | Sextet 3: bits 5-0
    (*base64_str)[write_index++] = base64_chars[(block >> 18) & 0x3F];
    (*base64_str)[write_index++] = base64_chars[(block >> 12) & 0x3F];
    (*base64_str)[write_index++] = base64_chars[(block >> 6) & 0x3F];
    (*base64_str)[write_index++] = base64_chars[block & 0x3F];

    read_index += 3;
  }

  // Process the remaining bytes (if any) with padding
  if (remainder == 1) {
    // 1 remaining byte: encode to 2 characters + 2 padding characters
    uint32_t block = (uint32_t)byte_array->buffer[read_index] << 16;

    (*base64_str)[write_index++] = base64_chars[(block >> 18) & 0x3F];
    (*base64_str)[write_index++] = base64_chars[(block >> 12) & 0x3F];
    (*base64_str)[write_index++] = '=';
    (*base64_str)[write_index++] = '=';
  } else if (remainder == 2) {
    // 2 remaining bytes: encode to 3 characters + 1 padding character
    uint32_t block =
      ((uint32_t)byte_array->buffer[read_index] << 16) |
      ((uint32_t)byte_array->buffer[read_index + 1] << 8);

    (*base64_str)[write_index++] = base64_chars[(block >> 18) & 0x3F];
    (*base64_str)[write_index++] = base64_chars[(block >> 12) & 0x3F];
    (*base64_str)[write_index++] = base64_chars[(block >> 6) & 0x3F];
    (*base64_str)[write_index++] = '=';
  }

  // Null-terminate the string
  (*base64_str)[write_index] = '\0';

  return RCUTILS_RET_OK;
}

rcutils_char_array_t
rcutils_get_zero_initialized_char_array(void)
{
  static rcutils_char_array_t char_array = {0};
  return char_array;
}

rcutils_ret_t
rcutils_char_array_init(
  rcutils_char_array_t * char_array,
  size_t buffer_capacity,
  const rcutils_allocator_t * allocator)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(char_array, RCUTILS_RET_ERROR);
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    allocator, "char array has no valid allocator",
    return RCUTILS_RET_ERROR);

  char_array->owns_buffer = true;
  char_array->buffer_length = 0lu;
  char_array->buffer_capacity = buffer_capacity;
  char_array->allocator = *allocator;

  if (buffer_capacity > 0lu) {
    char_array->buffer =
      (char *)allocator->allocate(buffer_capacity * sizeof(char), allocator->state);
    RCUTILS_CHECK_FOR_NULL_WITH_MSG(
      char_array->buffer,
      "failed to allocate memory for char array",
      char_array->buffer_capacity = 0lu;
      char_array->buffer_length = 0lu;
      return RCUTILS_RET_BAD_ALLOC);
    char_array->buffer[0] = '\0';
  }

  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_char_array_fini(rcutils_char_array_t * char_array)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(char_array, RCUTILS_RET_ERROR);

  if (char_array->owns_buffer) {
    rcutils_allocator_t * allocator = &char_array->allocator;
    RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
      allocator, "char array has no valid allocator",
      return RCUTILS_RET_ERROR);

    allocator->deallocate(char_array->buffer, allocator->state);
  }

  char_array->buffer = NULL;
  char_array->buffer_length = 0lu;
  char_array->buffer_capacity = 0lu;

  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_char_array_resize(rcutils_char_array_t * char_array, size_t new_size)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(char_array, RCUTILS_RET_ERROR);

  if (0lu == new_size) {
    RCUTILS_SET_ERROR_MSG("new size of char_array has to be greater than zero");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }

  rcutils_allocator_t * allocator = &char_array->allocator;
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    allocator, "char array has no valid allocator",
    return RCUTILS_RET_ERROR);

  if (new_size == char_array->buffer_capacity) {
    // nothing to do here
    return RCUTILS_RET_OK;
  }

  char * old_buf = char_array->buffer;
  size_t old_size = char_array->buffer_capacity;
  size_t old_length = char_array->buffer_length;

  if (char_array->owns_buffer) {  // we own the buffer, we can do whatever we want
    char * new_buf = rcutils_reallocf(char_array->buffer, new_size * sizeof(char), allocator);
    RCUTILS_CHECK_FOR_NULL_WITH_MSG(
      new_buf,
      "failed to reallocate memory for char array",
      return RCUTILS_RET_BAD_ALLOC);
    char_array->buffer = new_buf;
  } else {  // we don't realloc memory we don't own. instead, we alloc some new space
    rcutils_ret_t ret = rcutils_char_array_init(char_array, new_size, allocator);
    if (ret != RCUTILS_RET_OK) {
      return ret;
    }
    size_t n = MIN(new_size, old_size);
    memcpy(char_array->buffer, old_buf, n);
    char_array->buffer[n - 1] = '\0';  // always have an ending
  }

  char_array->buffer_capacity = new_size;
  char_array->buffer_length = MIN(new_size, old_length);

  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_char_array_expand_as_needed(rcutils_char_array_t * char_array, size_t new_size)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(char_array, RCUTILS_RET_ERROR);

  if (new_size <= char_array->buffer_capacity) {
    return RCUTILS_RET_OK;
  }

  // Make sure we expand by at least 1.5x the old capacity
  size_t minimum_size = char_array->buffer_capacity + (char_array->buffer_capacity >> 1);
  if (new_size < minimum_size) {
    new_size = minimum_size;
  }

  return rcutils_char_array_resize(char_array, new_size);
}

static int
_rcutils_char_array_vsprintf(rcutils_char_array_t * char_array, const char * format, va_list args)
{
  va_list args_clone;
  va_copy(args_clone, args);

  // when doing size calculation, remember the return value of vsnprintf excludes terminating null
  // byte
  int size = vsnprintf(char_array->buffer, char_array->buffer_capacity, format, args_clone);

  va_end(args_clone);

  return size;
}

rcutils_ret_t
rcutils_char_array_vsprintf(rcutils_char_array_t * char_array, const char * format, va_list args)
{
  int size = _rcutils_char_array_vsprintf(char_array, format, args);

  if (size < 0) {
    RCUTILS_SET_ERROR_MSG("vsprintf on char array failed");
    return RCUTILS_RET_ERROR;
  }

  size_t new_size = (size_t) size + 1;  // with the terminating null byte

  if (new_size > char_array->buffer_capacity) {
    rcutils_ret_t ret = rcutils_char_array_expand_as_needed(char_array, new_size);
    if (ret != RCUTILS_RET_OK) {
      // rcutils_char_array_expand_as_needed already set the error
      return ret;
    }

    if (_rcutils_char_array_vsprintf(char_array, format, args) != size) {
      if (rcutils_char_array_fini(char_array) == RCUTILS_RET_OK) {
        RCUTILS_SET_ERROR_MSG("vsprintf on resized char array failed");
      } else {
        RCUTILS_SET_ERROR_MSG("vsprintf on resized char array failed; clean up failed too");
      }
      return RCUTILS_RET_ERROR;
    }
  }

  char_array->buffer_length = new_size;

  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_char_array_memcpy(rcutils_char_array_t * char_array, const char * src, size_t n)
{
  rcutils_ret_t ret = rcutils_char_array_expand_as_needed(char_array, n);
  if (ret != RCUTILS_RET_OK) {
    // rcutils_char_array_expand_as needed already set the error
    return ret;
  }
  memcpy(char_array->buffer, src, n);
  char_array->buffer_length = n;
  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_char_array_strcpy(rcutils_char_array_t * char_array, const char * src)
{
  return rcutils_char_array_memcpy(char_array, src, strlen(src) + 1);
}

rcutils_ret_t
rcutils_char_array_strncat(rcutils_char_array_t * char_array, const char * src, size_t n)
{
  size_t current_strlen;
  if (char_array->buffer_length == 0) {
    current_strlen = 0;
  } else {
    // The buffer length always contains the trailing \0, so the strlen is one less than that.
    current_strlen = char_array->buffer_length - 1;
  }
  size_t new_length = current_strlen + n + 1;
  rcutils_ret_t ret = rcutils_char_array_expand_as_needed(char_array, new_length);
  if (ret != RCUTILS_RET_OK) {
    // rcutils_char_array_expand_as_needed already set the error
    return ret;
  }

  memcpy(char_array->buffer + current_strlen, src, n);
  char_array->buffer[new_length - 1] = '\0';

  char_array->buffer_length = new_length;
  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_char_array_strcat(rcutils_char_array_t * char_array, const char * src)
{
  return rcutils_char_array_strncat(char_array, src, strlen(src));
}

bool rcutils_cli_option_exist(char ** begin, char ** end, const char * option)
{
  // return std::find(begin, end, option) != end;
  for (size_t i = 0; i < (size_t)(end - begin); ++i) {
    if (strcmp(begin[i], option) == 0) {
      return true;
    }
  }
  return false;
}

char * rcutils_cli_get_option(char ** begin, char ** end, const char * option)
{
  size_t idx = 0;
  size_t end_idx = (size_t)(end - begin);
  for (; idx < end_idx; ++idx) {
    if (strncmp(begin[idx], option, strlen(option)) == 0) {
      break;
    }
  }

  if (idx < end_idx - 1 && begin[idx++] != NULL) {
    return begin[idx];
  }

  return NULL;
}

bool
rcutils_set_env(const char * env_name, const char * env_value)
{
  return rcutils_set_env_overwrite(env_name, env_value, true);
}

bool
rcutils_set_env_overwrite(const char * env_name, const char * env_value, bool overwrite)
{
  RCUTILS_CAN_RETURN_WITH_ERROR_OF(false);

  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    env_name, "env_name is null", return false);

  if ((int)overwrite == 0 && getenv(env_name) != NULL) {
    return true;
  }

  int set_ret;
#ifdef _WIN32
  if (NULL == env_value) {
    env_value = "";
  }
  set_ret = _putenv_s(env_name, env_value);
#else
  if (NULL == env_value) {
    set_ret = unsetenv(env_name);
  } else {
    set_ret = setenv(env_name, env_value, (int) overwrite);
  }
#endif

  if (set_ret != 0) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING("setting environment variable failed: %d", errno);
    return false;
  }

  return true;
}

const char *
rcutils_get_env(const char * env_name, const char ** env_value)
{
  RCUTILS_CAN_RETURN_WITH_ERROR_OF("some string error");

  if (NULL == env_name) {
    return "argument env_name is null";
  }
  if (NULL == env_value) {
    return "argument env_value is null";
  }

  // TODO(Suyash458): getenv is deprecated on Windows; consider using getenv_s instead
  *env_value = getenv(env_name);

  if (NULL == *env_value) {
    *env_value = "";
  }
  return NULL;
}

const char *
rcutils_get_home_dir(void)
{
  const char * homedir;

  if (rcutils_get_env("HOME", &homedir) == NULL && *homedir != '\0') {
    // The HOME environment variable was set and is non-empty, return it.
    return homedir;
  }

#ifdef _WIN32
  // We didn't find a HOME variable, try USERPROFILE on Windows.
  if (rcutils_get_env("USERPROFILE", &homedir) == NULL && *homedir != '\0') {
    // The USERPROFILE environment variable was set and is non-empty, return it.
    return homedir;
  }
#endif

  // Couldn't get the home directory, return NULL.
  return NULL;
}

rcutils_ret_t
rcutils_initialize_error_handling_thread_local_storage(rcutils_allocator_t allocator)
{
  if (gtls_rcutils_thread_local_initialized) {
    return RCUTILS_RET_OK;
  }

  // check if the given allocator is valid
  if (!rcutils_allocator_is_valid(&allocator)) {
#if RCUTILS_REPORT_ERROR_HANDLING_ERRORS
    RCUTILS_SAFE_FWRITE_TO_STDERR(
      "[rcutils|error_handling.c:" RCUTILS_STRINGIFY(__LINE__)
      "] rcutils_initialize_error_handling_thread_local_storage() given invalid allocator\n");
#endif
    return RCUTILS_RET_INVALID_ARGUMENT;
  }
  // right now the allocator is not used for anything
  // but other future implementations may need to use it
  // e.g. pthread which could only provide thread-local pointers would need to
  // allocate memory to which those pointers would point

  // forcing the values back to their initial state should force the thread-local storage
  // to initialize and do any required memory allocation
  gtls_rcutils_thread_local_initialized = true;
  rcutils_reset_error();
  RCUTILS_SET_ERROR_MSG("no error - initializing thread-local storage");
  rcutils_error_string_t throw_away = rcutils_get_error_string();
  (void)throw_away;
  rcutils_reset_error();

  // at this point the thread-local allocator, error state, and error string are all initialized
  return RCUTILS_RET_OK;
}

static
bool
__same_string(const char * str1, const char * str2, size_t count)
{
  assert(NULL != str1);
  assert(NULL != str2);
  return str1 == str2 || 0 == strncmp(str1, str2, count);
}

static
void
__format_overwriting_error_state_message(
  char * buffer,
  size_t buffer_size,
  const rcutils_error_state_t * new_error_state)
{
  assert(NULL != buffer);
  assert(0 != buffer_size);
  assert(SIZE_MAX > buffer_size);
  assert(NULL != new_error_state);

  int64_t bytes_left = (int64_t)buffer_size;
  do {
    char * offset = buffer;
    size_t written = 0;

    // write the first static part of the error message
    written = __rcutils_copy_string(
      offset, (size_t)bytes_left,
      "\n"
      ">>> [rcutils|error_handling.c:" RCUTILS_STRINGIFY(__LINE__) "] rcutils_set_error_state()\n"
      "This error state is being overwritten:\n"
      "\n"
      "  '");
    offset += written;
    bytes_left -= (int64_t)written;
    if (0 >= bytes_left) {break;}

    // write the old error string
    rcutils_error_string_t old_error_string = rcutils_get_error_string();
    written = __rcutils_copy_string(offset, sizeof(old_error_string.str), old_error_string.str);
    offset += written;
    bytes_left -= (int64_t)written;
    if (0 >= bytes_left) {break;}

    // write the middle part of the state error message
    written = __rcutils_copy_string(
      offset, (size_t)bytes_left,
      "'\n"
      "\n"
      "with this new error message:\n"
      "\n"
      "  '");
    offset += written;
    bytes_left -= (int64_t)written;
    if (0 >= bytes_left) {break;}

    // format error string for new error state and write it in
    rcutils_error_string_t new_error_string = {
      .str = "\0"
    };
    __rcutils_format_error_string(&new_error_string, new_error_state);
    written = __rcutils_copy_string(offset, sizeof(new_error_string.str), new_error_string.str);
    offset += written;
    bytes_left -= (int64_t)written;
    if (0 >= bytes_left) {break;}

    // write the last part of the state error message
    written = __rcutils_copy_string(
      offset, (size_t)bytes_left,
      "'\n"
      "\n"
      "rcutils_reset_error() should be called after error handling to avoid this.\n"
      "<<<\n");
    bytes_left -= (int64_t)written;
  } while (0);

#if RCUTILS_REPORT_ERROR_HANDLING_ERRORS
  // note that due to the way truncating is done above, and the size of the
  // output buffer used with this function in rcutils_set_error_state() below,
  // this should never evaluate to true, but it's here to be defensive and try
  // to catch programming mistakes in this file earlier.
  if (0 >= bytes_left) {
    RCUTILS_SAFE_FWRITE_TO_STDERR(
      "[rcutils|error_handling.c:" RCUTILS_STRINGIFY(__LINE__)
      "] rcutils_set_error_state() following error message was too long and will be truncated\n");
  }
#else
  (void)bytes_left;  // avoid scope could be reduced warning if in this case
#endif
}

void
rcutils_set_error_state(
  const char * error_string,
  const char * file,
  size_t line_number)
{
  rcutils_error_state_t error_state;

  if (NULL == error_string) {
#if RCUTILS_REPORT_ERROR_HANDLING_ERRORS
    RCUTILS_SAFE_FWRITE_TO_STDERR(
      "[rcutils|error_handling.c:" RCUTILS_STRINGIFY(__LINE__)
      "] rcutils_set_error_state() given null pointer for error_string, error was not set\n");
#endif
    return;
  }

  if (NULL == file) {
#if RCUTILS_REPORT_ERROR_HANDLING_ERRORS
    RCUTILS_SAFE_FWRITE_TO_STDERR(
      "[rcutils|error_handling.c:" RCUTILS_STRINGIFY(__LINE__)
      "] rcutils_set_error_state() given null pointer for file string, error was not set\n");
#endif
    return;
  }

  __rcutils_copy_string(error_state.message, sizeof(error_state.message), error_string);
  __rcutils_copy_string(error_state.file, sizeof(error_state.file), file);
  error_state.line_number = line_number;
#if RCUTILS_REPORT_ERROR_HANDLING_ERRORS
  // Only warn of overwritting if the new error is different from the old ones.
  size_t characters_to_compare = rcutils_strnlen(error_string, RCUTILS_ERROR_MESSAGE_MAX_LENGTH);
  // assumption is that message length is <= max error string length
  static_assert(
    sizeof(gtls_rcutils_error_state.message) <= sizeof(gtls_rcutils_error_string.str),
    "expected error state's max message length to be less than or equal to error string max");
  if (
    gtls_rcutils_error_is_set &&
    !__same_string(error_string, gtls_rcutils_error_string.str, characters_to_compare) &&
    !__same_string(error_string, gtls_rcutils_error_state.message, characters_to_compare))
  {
    char output_buffer[4096];
    __format_overwriting_error_state_message(output_buffer, sizeof(output_buffer), &error_state);
    RCUTILS_SAFE_FWRITE_TO_STDERR(output_buffer);
  }
#endif
  gtls_rcutils_error_state = error_state;
  gtls_rcutils_error_string_is_formatted = false;
  gtls_rcutils_error_string = (const rcutils_error_string_t) {
    .str = "\0"
  };
  gtls_rcutils_error_is_set = true;
}

bool
rcutils_error_is_set(void)
{
  return gtls_rcutils_error_is_set;
}

const rcutils_error_state_t *
rcutils_get_error_state(void)
{
  return &gtls_rcutils_error_state;
}

rcutils_error_string_t
rcutils_get_error_string(void)
{
  if (!gtls_rcutils_error_is_set) {
    return (rcutils_error_string_t) {"error not set"};  // NOLINT(readability/braces)
  }
  if (!gtls_rcutils_error_string_is_formatted) {
    __rcutils_format_error_string(&gtls_rcutils_error_string, &gtls_rcutils_error_state);
    gtls_rcutils_error_string_is_formatted = true;
  }
  return gtls_rcutils_error_string;
}

void
rcutils_reset_error(void)
{
  gtls_rcutils_error_state = (const rcutils_error_state_t) {
    .message = {0}, .file = {0}, .line_number = 0
  };  // NOLINT(readability/braces)
  gtls_rcutils_error_string_is_formatted = false;
  gtls_rcutils_error_string = (const rcutils_error_string_t) {
    .str = "\0"
  };
  gtls_rcutils_error_is_set = false;
}

bool
rcutils_get_cwd(char * buffer, size_t max_length)
{
  if (NULL == buffer || max_length == 0) {
    return false;
  }
#ifdef _WIN32
  if (NULL == _getcwd(buffer, (int)max_length)) {
    return false;
  }
#else
  if (NULL == getcwd(buffer, max_length)) {
    return false;
  }
#endif  // _WIN32
  return true;
}

bool
rcutils_is_directory(const char * abs_path)
{
  struct stat buf;
  if (stat(abs_path, &buf) < 0) {
    return false;
  }
#ifdef _WIN32
  return (buf.st_mode & S_IFDIR) == S_IFDIR;
#else
  return S_ISDIR(buf.st_mode);
#endif  // _WIN32
}

bool
rcutils_is_file(const char * abs_path)
{
  struct stat buf;
  if (stat(abs_path, &buf) < 0) {
    return false;
  }
#ifdef _WIN32
  return (buf.st_mode & S_IFREG) == S_IFREG;
#else
  return S_ISREG(buf.st_mode);
#endif  // _WIN32
}

bool
rcutils_exists(const char * abs_path)
{
  struct stat buf;
  if (stat(abs_path, &buf) < 0) {
    return false;
  }
  return true;
}

char *
rcutils_join_path(
  const char * left_hand_path,
  const char * right_hand_path,
  rcutils_allocator_t allocator)
{
  if (NULL == left_hand_path) {
    return NULL;
  }
  if (NULL == right_hand_path) {
    return NULL;
  }

  return rcutils_format_string(
    allocator,
    "%s%s%s",
    left_hand_path, RCUTILS_PATH_DELIMITER, right_hand_path);
}

char *
rcutils_to_native_path(
  const char * path,
  rcutils_allocator_t allocator)
{
  if (NULL == path) {
    return NULL;
  }

  return rcutils_repl_str(path, "/", RCUTILS_PATH_DELIMITER, &allocator);
}

char *
rcutils_expand_user(const char * path, rcutils_allocator_t allocator)
{
  if (NULL == path) {
    return NULL;
  }

  if ('~' != path[0]) {
    return rcutils_strdup(path, allocator);
  }

  const char * homedir = rcutils_get_home_dir();
  if (NULL == homedir) {
    return NULL;
  }
  return rcutils_format_string_limit(
    allocator,
    strlen(homedir) + strlen(path),
    "%s%s",
    homedir,
    path + 1);
}

bool
rcutils_mkdir(const char * abs_path)
{
  if (NULL == abs_path) {
    return false;
  }

  if (abs_path[0] == '\0') {
    return false;
  }

  bool success = false;
#ifdef _WIN32
  // TODO(clalancette): Check to ensure that the path is absolute on Windows.
  // In theory we can use PathRelativeA to do this, but I was unable to make
  // it work.  Needs further investigation.

  int ret = _mkdir(abs_path);
#else
  if (abs_path[0] != '/') {
    return false;
  }

  int ret = mkdir(abs_path, 0775);
#endif
  if (ret == 0 || (errno == EEXIST && rcutils_is_directory(abs_path))) {
    success = true;
  }

  return success;
}

rcutils_ret_t
rcutils_calculate_directory_size(
  const char * directory_path,
  uint64_t * size,
  rcutils_allocator_t allocator)
{
  return rcutils_calculate_directory_size_with_recursion(directory_path, 1, size, allocator);
}

static void free_dir_list(dir_list_t * dir_list, rcutils_allocator_t allocator)
{
  dir_list_t * next_dir;
  do {
    next_dir = dir_list->next;
    allocator.deallocate(dir_list->path, allocator.state);
    allocator.deallocate(dir_list, allocator.state);
    dir_list = next_dir;
  } while (dir_list);
}

static void remove_first_dir_from_list(dir_list_t ** dir_list, rcutils_allocator_t allocator)
{
  dir_list_t * next_dir = (*dir_list)->next;
  allocator.deallocate((*dir_list)->path, allocator.state);
  allocator.deallocate(*dir_list, allocator.state);
  *dir_list = next_dir;
}

static rcutils_ret_t check_and_calculate_size(
  const char * filename,
  uint64_t * dir_size,
  const size_t max_depth,
  dir_list_t * dir_list,
  rcutils_allocator_t allocator)
{
  // Skip over local folder handle (`.`) and parent folder (`..`)
  if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) {
    return RCUTILS_RET_OK;
  }

  char * file_path = rcutils_join_path(dir_list->path, filename, allocator);
  if (NULL == file_path) {
    RCUTILS_SAFE_FWRITE_TO_STDERR("rcutils_join_path return NULL !\n");
    return RCUTILS_RET_BAD_ALLOC;
  }

  if (rcutils_is_directory(file_path)) {
    if ((max_depth == 0) || ((dir_list->depth + 1) <= max_depth)) {
      // Add new directory to dir_list
      dir_list_t * found_new_dir =
        allocator.allocate(sizeof(dir_list_t), allocator.state);
      if (NULL == found_new_dir) {
        RCUTILS_SAFE_FWRITE_TO_STDERR_WITH_FORMAT_STRING(
          "Failed to allocate memory for path %s !\n", file_path);
        allocator.deallocate(file_path, allocator.state);
        return RCUTILS_RET_BAD_ALLOC;
      }
      found_new_dir->path = file_path;
      found_new_dir->depth = dir_list->depth + 1;
      found_new_dir->next = dir_list->next;
      dir_list->next = found_new_dir;
      return RCUTILS_RET_OK;
    }
  } else {
    *dir_size += rcutils_get_file_size(file_path);
  }

  allocator.deallocate(file_path, allocator.state);

  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_calculate_directory_size_with_recursion(
  const char * directory_path,
  const size_t max_depth,
  uint64_t * size,
  rcutils_allocator_t allocator)
{
  dir_list_t * dir_list = NULL;
  rcutils_ret_t ret = RCUTILS_RET_OK;
  rcutils_dir_iter_t * iter = NULL;

  if (NULL == directory_path) {
    RCUTILS_SAFE_FWRITE_TO_STDERR("directory_path is NULL !");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }

  if (NULL == size) {
    RCUTILS_SAFE_FWRITE_TO_STDERR("size pointer is NULL !");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }

  if (!rcutils_is_directory(directory_path)) {
    RCUTILS_SAFE_FWRITE_TO_STDERR_WITH_FORMAT_STRING(
      "Path is not a directory: %s\n", directory_path);
    return RCUTILS_RET_ERROR;
  }

  RCUTILS_CHECK_ALLOCATOR(&allocator, return RCUTILS_RET_INVALID_ARGUMENT);
  dir_list = allocator.zero_allocate(1, sizeof(dir_list_t), allocator.state);
  if (NULL == dir_list) {
    RCUTILS_SAFE_FWRITE_TO_STDERR("Failed to allocate memory !\n");
    return RCUTILS_RET_BAD_ALLOC;
  }

  dir_list->depth = 1;

  dir_list->path = rcutils_strdup(directory_path, allocator);
  if (NULL == dir_list->path) {
    RCUTILS_SAFE_FWRITE_TO_STDERR("Failed to duplicate directory path !\n");
    allocator.deallocate(dir_list, allocator.state);
    return RCUTILS_RET_BAD_ALLOC;
  }

  *size = 0;

  do {
    iter = rcutils_dir_iter_start(dir_list->path, allocator);
    if (NULL == iter) {
      ret = RCUTILS_RET_ERROR;
      goto fail;
    }

    do {
      ret = check_and_calculate_size(iter->entry_name, size, max_depth, dir_list, allocator);
      if (RCUTILS_RET_OK != ret) {
        goto fail;
      }
    } while (rcutils_dir_iter_next(iter));

    rcutils_dir_iter_end(iter);

    remove_first_dir_from_list(&dir_list, allocator);
  } while (dir_list);

  return ret;

fail:
  rcutils_dir_iter_end(iter);
  free_dir_list(dir_list, allocator);
  return ret;
}

rcutils_dir_iter_t *
rcutils_dir_iter_start(const char * directory_path, const rcutils_allocator_t allocator)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(directory_path, NULL);
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    &allocator, "allocator is invalid", return NULL);

  rcutils_dir_iter_t * iter = allocator.zero_allocate(
    1, sizeof(rcutils_dir_iter_t), allocator.state);
  if (NULL == iter) {
    return NULL;
  }
  iter->allocator = allocator;

  iter->state = allocator.zero_allocate(
    1, sizeof(rcutils_dir_iter_state_t), allocator.state);
  if (NULL == iter->state) {
    RCUTILS_SET_ERROR_MSG(
      "Failed to allocate memory.\n");
    goto rcutils_dir_iter_start_fail;
  }

#ifdef _WIN32
  char * search_path = rcutils_join_path(directory_path, "*", allocator);
  if (NULL == search_path) {
    goto rcutils_dir_iter_start_fail;
  }
  iter->state->handle = FindFirstFile(search_path, &iter->state->data);
  allocator.deallocate(search_path, allocator.state);
  if (INVALID_HANDLE_VALUE == iter->state->handle) {
    DWORD error = GetLastError();
    if (ERROR_FILE_NOT_FOUND != error || !rcutils_is_directory(directory_path)) {
      RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
        "Can't open directory %s. Error code: %d\n", directory_path, error);
      goto rcutils_dir_iter_start_fail;
    }
  } else {
    iter->entry_name = iter->state->data.cFileName;
  }
#else
  iter->state->dir = opendir(directory_path);
  if (NULL == iter->state->dir) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "Can't open directory %s. Error code: %d\n", directory_path, errno);
    goto rcutils_dir_iter_start_fail;
  }

  errno = 0;
  struct dirent * entry = readdir(iter->state->dir);
  if (NULL != entry) {
    iter->entry_name = entry->d_name;
  } else if (0 != errno) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "Can't iterate directory %s. Error code: %d\n", directory_path, errno);
    goto rcutils_dir_iter_start_fail;
  }
#endif

  return iter;

rcutils_dir_iter_start_fail:
  rcutils_dir_iter_end(iter);
  return NULL;
}

bool
rcutils_dir_iter_next(rcutils_dir_iter_t * iter)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(iter, false);
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(iter->state, "iter is invalid", return false);

#ifdef _WIN32
  if (FindNextFile(iter->state->handle, &iter->state->data)) {
    iter->entry_name = iter->state->data.cFileName;
    return true;
  }
#else
  struct dirent * entry = readdir(iter->state->dir);
  if (NULL != entry) {
    iter->entry_name = entry->d_name;
    return true;
  }
#endif

  iter->entry_name = NULL;
  return false;
}

void
rcutils_dir_iter_end(rcutils_dir_iter_t * iter)
{
  if (NULL == iter) {
    return;
  }

  rcutils_allocator_t allocator = iter->allocator;
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    &allocator, "allocator is invalid", return );

  if (NULL != iter->state) {
#ifdef _WIN32
    FindClose(iter->state->handle);
#else
    if (NULL != iter->state->dir) {
      closedir(iter->state->dir);
    }
#endif

    allocator.deallocate(iter->state, allocator.state);
  }

  allocator.deallocate(iter, allocator.state);
}

size_t
rcutils_get_file_size(const char * file_path)
{
  if (!rcutils_is_file(file_path)) {
    RCUTILS_SAFE_FWRITE_TO_STDERR_WITH_FORMAT_STRING(
      "Path is not a file: %s\n", file_path);
    return 0;
  }

  struct stat stat_buffer;
  int rc = stat(file_path, &stat_buffer);
  return rc == 0 ? (size_t)(stat_buffer.st_size) : 0;
}

size_t
rcutils_find(const char * str, char delimiter)
{
  if (NULL == str || 0 == strlen(str)) {
    return SIZE_MAX;
  }
  return rcutils_findn(str, delimiter, strlen(str));
}

size_t
rcutils_findn(const char * str, char delimiter, size_t string_length)
{
  if (NULL == str || 0 == string_length) {
    return SIZE_MAX;
  }

  for (size_t i = 0; i < string_length; ++i) {
    if (str[i] == delimiter) {
      return i;
    }
  }
  return SIZE_MAX;
}

size_t
rcutils_find_last(const char * str, char delimiter)
{
  if (NULL == str || 0 == strlen(str)) {
    return SIZE_MAX;
  }
  return rcutils_find_lastn(str, delimiter, strlen(str));
}

size_t
rcutils_find_lastn(const char * str, char delimiter, size_t string_length)
{
  if (NULL == str || 0 == string_length) {
    return SIZE_MAX;
  }

#if defined(_GNU_SOURCE)
  const char * ptr = memrchr(str, delimiter, string_length);
  if (ptr == NULL) {
    return SIZE_MAX;
  }

  return ptr - str;
#else
  for (size_t i = string_length - 1; i > 0; --i) {
    if (str[i] == delimiter) {
      return i;
    }
  }
  return str[0] == delimiter ? 0 : SIZE_MAX;
#endif
}

char *
rcutils_format_string_limit(
  rcutils_allocator_t allocator,
  size_t limit,
  const char * format_string,
  ...)
{
  if (NULL == format_string) {
    return NULL;
  }
  RCUTILS_CHECK_ALLOCATOR(&allocator, return NULL);
  // extract the variadic arguments twice, once for length calculatio and once for formatting.
  va_list args1;
  va_start(args1, format_string);
  va_list args2;
  va_copy(args2, args1);
  // first calculate the output string
  size_t bytes_to_be_written = (size_t)rcutils_vsnprintf(NULL, 0, format_string, args1);
  va_end(args1);
  if (bytes_to_be_written == (size_t)-1) {
    va_end(args2);
    return NULL;
  }
  // allocate space for the return string
  if (bytes_to_be_written + 1 > limit) {
    bytes_to_be_written = limit - 1;
  }
  char * output_string = allocator.allocate(bytes_to_be_written + 1, allocator.state);
  if (NULL == output_string) {
    va_end(args2);
    return NULL;
  }
  // format the string
  int ret = rcutils_vsnprintf(output_string, bytes_to_be_written + 1, format_string, args2);
  if (0 > ret) {
    allocator.deallocate(output_string, allocator.state);
    va_end(args2);
    return NULL;
  }
  output_string[bytes_to_be_written] = '\0';
  va_end(args2);
  return output_string;
}

size_t rcutils_hash_map_string_hash_func(const void * key_str)
{
  const char ** ckey_ptr = (const char **) key_str;
  const char * ckey_str = *ckey_ptr;
  size_t hash = 5381;

  while ('\0' != *ckey_str) {
    const char c = *(ckey_str++);
    hash = ((hash << 5) + hash) + (size_t)c; /* hash * 33 + c */
  }

  return hash;
}

int rcutils_hash_map_string_cmp_func(const void * val1, const void * val2)
{
  const char ** cval1 = (const char **) val1;
  const char ** cval2 = (const char **) val2;
  return strcmp(*cval1, *cval2);
}

rcutils_hash_map_t
rcutils_get_zero_initialized_hash_map(void)
{
  static rcutils_hash_map_t zero_initialized_hash_map = {0};
  return zero_initialized_hash_map;
}

static rcutils_ret_t hash_map_allocate_new_map(
  rcutils_array_list_t ** map, size_t capacity,
  const rcutils_allocator_t * allocator)
{
  *map = allocator->allocate(capacity * sizeof(rcutils_hash_map_impl_t), allocator->state);
  if (NULL == *map) {
    return RCUTILS_RET_BAD_ALLOC;
  }

  // Make sure the list for every bucket is zero initialized
  rcutils_array_list_t zero_list = rcutils_get_zero_initialized_array_list();
  for (size_t i = 0; i < capacity; ++i) {
    (*map)[i] = zero_list;
  }

  return RCUTILS_RET_OK;
}

static void hash_map_deallocate_entry(
  rcutils_allocator_t * allocator,
  rcutils_hash_map_entry_t * entry)
{
  if (NULL != entry) {
    allocator->deallocate(entry->key, allocator->state);
    allocator->deallocate(entry->value, allocator->state);
    allocator->deallocate(entry, allocator->state);
  }
}

static rcutils_ret_t hash_map_deallocate_map(
  rcutils_array_list_t * map, size_t capacity,
  rcutils_allocator_t * allocator, bool dealloc_map_entries)
{
  rcutils_ret_t ret = RCUTILS_RET_OK;
  for (size_t i = 0; i < capacity && RCUTILS_RET_OK == ret; ++i) {
    // If an array list is allocated for this bucket then clean it up
    rcutils_array_list_t * bucket = &(map[i]);
    if (NULL != bucket->impl) {
      // if selected then deallocate the memory for the actual entries as well
      if (dealloc_map_entries) {
        size_t bucket_size = 0;
        ret = rcutils_array_list_get_size(bucket, &bucket_size);
        for (size_t b_i = 0; b_i < bucket_size && RCUTILS_RET_OK == ret; ++b_i) {
          rcutils_hash_map_entry_t * entry;
          ret = rcutils_array_list_get(bucket, b_i, &entry);
          if (RCUTILS_RET_OK == ret) {
            hash_map_deallocate_entry(allocator, entry);
          }
        }
      }

      // Cleanup the actual list itself
      if (RCUTILS_RET_OK == ret) {
        ret = rcutils_array_list_fini(bucket);
      }
    }
  }

  // Cleanup the memory allocated for the array of buckets
  if (RCUTILS_RET_OK == ret) {
    allocator->deallocate(map, allocator->state);
  }

  return ret;
}

static rcutils_ret_t hash_map_insert_entry(
  rcutils_array_list_t * map,
  size_t bucket_index,
  const rcutils_hash_map_entry_t * entry,
  rcutils_allocator_t * allocator)
{
  rcutils_array_list_t * bucket = &(map[bucket_index]);
  rcutils_ret_t ret = RCUTILS_RET_OK;

  // If we have initialized this bucket yet then do so
  if (NULL == bucket->impl) {
    ret = rcutils_array_list_init(
      bucket, BUCKET_INITIAL_CAP, sizeof(rcutils_hash_map_entry_t *), allocator);
  }

  if (RCUTILS_RET_OK == ret) {
    ret = rcutils_array_list_add(bucket, &entry);
  }

  return ret;
}

static rcutils_ret_t hash_map_check_and_grow_map(rcutils_hash_map_t * hash_map)
{
  rcutils_ret_t ret = RCUTILS_RET_OK;
  if (hash_map->impl->size >= (size_t)(LOAD_FACTOR * (double)hash_map->impl->capacity)) {
    size_t new_capacity = 2 * hash_map->impl->capacity;
    rcutils_array_list_t * new_map = NULL;

    ret = hash_map_allocate_new_map(&new_map, new_capacity, &hash_map->impl->allocator);
    if (RCUTILS_RET_OK != ret) {
      return ret;
    }

    for (size_t map_index = 0;
      map_index < hash_map->impl->capacity && RCUTILS_RET_OK == ret;
      ++map_index)
    {
      rcutils_array_list_t * bucket = &(hash_map->impl->map[map_index]);
      // Is this a valid bucket with entries
      if (NULL != bucket->impl) {
        size_t bucket_size = 0;
        ret = rcutils_array_list_get_size(bucket, &bucket_size);
        if (RCUTILS_RET_OK != ret) {
          return ret;
        }

        for (size_t bucket_index = 0;
          bucket_index < bucket_size && RCUTILS_RET_OK == ret;
          ++bucket_index)
        {
          rcutils_hash_map_entry_t * entry = NULL;
          ret = rcutils_array_list_get(bucket, bucket_index, &entry);
          if (RCUTILS_RET_OK == ret) {
            size_t new_index = entry->hashed_key % new_capacity;
            ret = hash_map_insert_entry(new_map, new_index, entry, &hash_map->impl->allocator);
          }
        }
      }
    }

    // Something went wrong above after we allocated the new map. Try to clean it up
    if (RCUTILS_RET_OK != ret) {
      hash_map_deallocate_map(new_map, new_capacity, &hash_map->impl->allocator, false);
      return ret;
    }

    // Cleanup the old map and swap in the new one
    ret = hash_map_deallocate_map(
      hash_map->impl->map, hash_map->impl->capacity, &hash_map->impl->allocator, false);
    // everything worked up to this point, so if we fail to dealloc the old map still set the new
    hash_map->impl->map = new_map;
    hash_map->impl->capacity = new_capacity;
  }

  return ret;
}

static size_t next_power_of_two(size_t v)
{
  size_t shf = 0;
  v--;
  for (size_t i = 0; shf < sizeof(size_t) * 4; ++i) {
    shf = (((size_t) 1) << i);
    v |= v >> shf;
  }
  v++;
  return v > 1 ? v : 1;
}

rcutils_ret_t
rcutils_hash_map_init(
  rcutils_hash_map_t * hash_map,
  size_t initial_capacity,
  size_t key_size,
  size_t data_size,
  rcutils_hash_map_key_hasher_t key_hashing_func,
  rcutils_hash_map_key_cmp_t key_cmp_func,
  const rcutils_allocator_t * allocator)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(hash_map, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(key_hashing_func, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(key_cmp_func, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ALLOCATOR(allocator, return RCUTILS_RET_INVALID_ARGUMENT);
  if (1 > initial_capacity) {
    RCUTILS_SET_ERROR_MSG("initial_capacity cannot be less than 1");
    return RCUTILS_RET_INVALID_ARGUMENT;
  } else if (1 > key_size) {
    RCUTILS_SET_ERROR_MSG("key_size cannot be less than 1");
    return RCUTILS_RET_INVALID_ARGUMENT;
  } else if (1 > data_size) {
    RCUTILS_SET_ERROR_MSG("data_size cannot be less than 1");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }

  // Due to an optimization we use during lookup, the capacity must be a power-of-two.
  // If the user passed us something that is not power-of-two, round up to the next power-of-two
  if ((initial_capacity & (initial_capacity - 1)) != 0) {
    initial_capacity = next_power_of_two(initial_capacity);
  }

  hash_map->impl = allocator->allocate(sizeof(rcutils_hash_map_impl_t), allocator->state);
  if (NULL == hash_map->impl) {
    RCUTILS_SET_ERROR_MSG("failed to allocate memory for hash map impl");
    return RCUTILS_RET_BAD_ALLOC;
  }

  hash_map->impl->capacity = initial_capacity;
  hash_map->impl->size = 0;
  hash_map->impl->key_size = key_size;
  hash_map->impl->data_size = data_size;
  hash_map->impl->key_hashing_func = key_hashing_func;
  hash_map->impl->key_cmp_func = key_cmp_func;

  rcutils_ret_t ret = hash_map_allocate_new_map(&hash_map->impl->map, initial_capacity, allocator);
  if (RCUTILS_RET_OK != ret) {
    // Cleanup allocated memory before we return failure
    allocator->deallocate(hash_map->impl, allocator->state);
    hash_map->impl = NULL;
    RCUTILS_SET_ERROR_MSG("failed to allocate memory for map data");
    return ret;
  }

  hash_map->impl->allocator = *allocator;

  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_hash_map_fini(rcutils_hash_map_t * hash_map)
{
  HASH_MAP_VALIDATE_HASH_MAP(hash_map);
  rcutils_ret_t ret = hash_map_deallocate_map(
    hash_map->impl->map, hash_map->impl->capacity, &hash_map->impl->allocator, true);

  if (RCUTILS_RET_OK == ret) {
    hash_map->impl->allocator.deallocate(hash_map->impl, hash_map->impl->allocator.state);
    hash_map->impl = NULL;
  }

  return ret;
}

rcutils_ret_t
rcutils_hash_map_get_capacity(const rcutils_hash_map_t * hash_map, size_t * capacity)
{
  HASH_MAP_VALIDATE_HASH_MAP(hash_map);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(capacity, RCUTILS_RET_INVALID_ARGUMENT);
  *capacity = hash_map->impl->capacity;
  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_hash_map_get_size(const rcutils_hash_map_t * hash_map, size_t * size)
{
  HASH_MAP_VALIDATE_HASH_MAP(hash_map);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(size, RCUTILS_RET_INVALID_ARGUMENT);
  *size = hash_map->impl->size;
  return RCUTILS_RET_OK;
}

static bool hash_map_find(
  const rcutils_hash_map_t * hash_map,   // [in] The hash_map to look up in
  const void * key,   // [in] The key to lookup
  size_t * key_hash,   // [out] The key's hashed value
  size_t * map_index,   // [out] The index into the array of buckets
  size_t * bucket_index,   // [out] The index of the entry in its bucket
  rcutils_hash_map_entry_t ** entry)   // [out] Will be set to a pointer to the entry's data
{
  size_t bucket_size = 0;
  rcutils_hash_map_entry_t * bucket_entry = NULL;

  *key_hash = hash_map->impl->key_hashing_func(key);
  // The below is equivalent to:
  //
  // *map_index = (*key_hash) % hash_map->impl->capacity;
  //
  // This implementation is significantly faster since it avoids a divide, but
  // only works when the capacity is a power of two.  We enforce that in the
  // rcutils_hash_map_init() function.
  *map_index = (*key_hash) & (hash_map->impl->capacity - 1);

  // Find the bucket the entry should be in check that it's valid
  rcutils_array_list_t * bucket = &(hash_map->impl->map[*map_index]);
  if (NULL == bucket->impl) {
    return false;
  }
  if (RCUTILS_RET_OK != rcutils_array_list_get_size(bucket, &bucket_size)) {
    return false;
  }
  for (size_t i = 0; i < bucket_size; ++i) {
    if (RCUTILS_RET_OK != rcutils_array_list_get(bucket, i, &bucket_entry)) {
      return false;
    }
    // Check that the hashes match first as that will be the quicker comparison to quick fail on
    if (bucket_entry->hashed_key == *key_hash &&
      (0 == hash_map->impl->key_cmp_func(bucket_entry->key, key)))
    {
      *bucket_index = i;
      *entry = bucket_entry;
      return true;
    }
  }

  return false;
}

rcutils_ret_t
rcutils_hash_map_set(rcutils_hash_map_t * hash_map, const void * key, const void * value)
{
  HASH_MAP_VALIDATE_HASH_MAP(hash_map);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(key, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(value, RCUTILS_RET_INVALID_ARGUMENT);

  size_t key_hash = 0, map_index = 0, bucket_index = 0;
  bool already_exists = false;
  rcutils_hash_map_entry_t * entry = NULL;
  rcutils_ret_t ret = RCUTILS_RET_OK;

  already_exists = hash_map_find(hash_map, key, &key_hash, &map_index, &bucket_index, &entry);

  if (already_exists) {
    // Just update the existing value to match the new value
    memcpy(entry->value, value, hash_map->impl->data_size);
  } else {
    // We need to create a new entry in the map
    rcutils_allocator_t * allocator = &hash_map->impl->allocator;
    RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
      allocator, "allocator is invalid", return RCUTILS_RET_INVALID_ARGUMENT);

    // Start by trying to allocate the memory we need for the new entry
    entry = allocator->allocate(sizeof(rcutils_hash_map_entry_t), allocator->state);
    if (NULL == entry) {
      return RCUTILS_RET_BAD_ALLOC;
    }
    entry->key = allocator->allocate(hash_map->impl->key_size, allocator->state);
    entry->value = allocator->allocate(hash_map->impl->data_size, allocator->state);
    if (NULL == entry->key || NULL == entry->value) {
      ret = RCUTILS_RET_BAD_ALLOC;
    }

    // Set the entry data and try to insert into the bucket
    if (RCUTILS_RET_OK == ret) {
      entry->hashed_key = key_hash;
      memcpy(entry->value, value, hash_map->impl->data_size);
      memcpy(entry->key, key, hash_map->impl->key_size);

      // See the comment in hash_map_find for why we do this.
      bucket_index = key_hash & (hash_map->impl->capacity - 1);
      ret = hash_map_insert_entry(hash_map->impl->map, bucket_index, entry, allocator);
    }

    if (RCUTILS_RET_OK != ret) {
      // If something went wrong somewhere then cleanup the memory we've allocated
      hash_map_deallocate_entry(allocator, entry);
      return ret;
    }
    hash_map->impl->size++;
  }

  // Time to check if we've exceeded our Load Factor and grow the map if so
  ret = hash_map_check_and_grow_map(hash_map);
  // Just log on this failure because the map can continue to operate with degraded performance
  RCUTILS_LOG_ERROR_EXPRESSION(RCUTILS_RET_OK != ret, "Failed to grow hash_map. Reason: %d", ret);

  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_hash_map_unset(rcutils_hash_map_t * hash_map, const void * key)
{
  HASH_MAP_VALIDATE_HASH_MAP(hash_map);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(key, RCUTILS_RET_INVALID_ARGUMENT);

  size_t key_hash = 0, map_index = 0, bucket_index = 0;
  bool already_exists = false;
  rcutils_hash_map_entry_t * entry = NULL;

  // If there is nothing in the hash map, don't bother computing the key
  if (hash_map->impl->size == 0) {
    return RCUTILS_RET_OK;
  }

  already_exists = hash_map_find(hash_map, key, &key_hash, &map_index, &bucket_index, &entry);

  if (!already_exists) {
    // The entry isn't in the map, so just exit
    return RCUTILS_RET_OK;
  }

  // Remove the entry from its bucket and deallocate it
  rcutils_array_list_t * bucket = &(hash_map->impl->map[map_index]);
  if (RCUTILS_RET_OK == rcutils_array_list_remove(bucket, bucket_index)) {
    hash_map->impl->size--;
    hash_map_deallocate_entry(&hash_map->impl->allocator, entry);
  }

  return RCUTILS_RET_OK;
}

bool
rcutils_hash_map_key_exists(const rcutils_hash_map_t * hash_map, const void * key)
{
  // Verify input
  if (NULL == hash_map) {
    return false;
  } else if (NULL == hash_map->impl) {
    return false;
  } else if (NULL == key) {
    return false;
  }

  size_t key_hash = 0, map_index = 0, bucket_index = 0;
  bool already_exists = false;
  rcutils_hash_map_entry_t * entry = NULL;

  // If there is nothing in the hash map, don't bother computing the key
  if (hash_map->impl->size == 0) {
    return RCUTILS_RET_OK;
  }

  already_exists = hash_map_find(hash_map, key, &key_hash, &map_index, &bucket_index, &entry);

  return already_exists;
}

rcutils_ret_t
rcutils_hash_map_get(const rcutils_hash_map_t * hash_map, const void * key, void * data)
{
  HASH_MAP_VALIDATE_HASH_MAP(hash_map);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(key, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(data, RCUTILS_RET_INVALID_ARGUMENT);

  size_t key_hash = 0, map_index = 0, bucket_index = 0;
  bool already_exists = false;
  rcutils_hash_map_entry_t * entry = NULL;

  // If there is nothing in the hash map, don't bother computing the key
  if (hash_map->impl->size == 0) {
    return RCUTILS_RET_NOT_FOUND;
  }

  already_exists = hash_map_find(hash_map, key, &key_hash, &map_index, &bucket_index, &entry);

  if (already_exists) {
    memcpy(data, entry->value, hash_map->impl->data_size);
    return RCUTILS_RET_OK;
  }

  return RCUTILS_RET_NOT_FOUND;
}

rcutils_ret_t
rcutils_hash_map_get_next_key_and_data(
  const rcutils_hash_map_t * hash_map,
  const void * previous_key,
  void * key,
  void * data)
{
  HASH_MAP_VALIDATE_HASH_MAP(hash_map);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(key, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(data, RCUTILS_RET_INVALID_ARGUMENT);

  size_t key_hash = 0, map_index = 0, bucket_index = 0;
  bool already_exists = false;
  rcutils_hash_map_entry_t * entry = NULL;
  rcutils_ret_t ret = RCUTILS_RET_OK;

  // If there is nothing in the hash map, don't bother computing the key
  if (hash_map->impl->size == 0) {
    if (NULL != previous_key) {
      return RCUTILS_RET_NOT_FOUND;
    } else {
      return RCUTILS_RET_HASH_MAP_NO_MORE_ENTRIES;
    }
  }

  if (NULL != previous_key) {
    already_exists = hash_map_find(
      hash_map, previous_key, &key_hash, &map_index, &bucket_index, &entry);
    if (!already_exists) {
      return RCUTILS_RET_NOT_FOUND;
    }
    bucket_index++;  // We want to start our search from the next object
  }

  for (; map_index < hash_map->impl->capacity; ++map_index) {
    rcutils_array_list_t * bucket = &(hash_map->impl->map[map_index]);
    if (NULL != bucket->impl) {
      size_t bucket_size = 0;
      ret = rcutils_array_list_get_size(bucket, &bucket_size);
      if (RCUTILS_RET_OK != ret) {
        return ret;
      }

      // Check if the next index in this bucket is valid and if so we've found the next item
      if (bucket_index < bucket_size) {
        rcutils_hash_map_entry_t * bucket_entry = NULL;
        ret = rcutils_array_list_get(bucket, bucket_index, &bucket_entry);
        if (RCUTILS_RET_OK == ret) {
          memcpy(key, bucket_entry->key, hash_map->impl->key_size);
          memcpy(data, bucket_entry->value, hash_map->impl->data_size);
        }

        return ret;
      }
    }
    // After the first bucket the next entry must be at the start of the next bucket with entries
    bucket_index = 0;
  }

  return RCUTILS_RET_HASH_MAP_NO_MORE_ENTRIES;
}

char *
rcutils_join(
  const rcutils_string_array_t * string_array,
  const char * separator,
  rcutils_allocator_t allocator)
{
  RCUTILS_CAN_RETURN_WITH_ERROR_OF(NULL);

  RCUTILS_CHECK_ARGUMENT_FOR_NULL(string_array, NULL);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(separator, NULL);
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    &allocator, "allocator is invalid", return NULL);

  if (string_array->size < 1) {
    return rcutils_strdup("", allocator);
  }

  size_t sep_length = strlen(separator);
  size_t string_length = sep_length * (string_array->size - 1);

  for (size_t i = 0; i < string_array->size; i++) {
    if (string_array->data[i]) {
      string_length += strlen(string_array->data[i]);
    }
  }

  char * new_string = allocator.allocate(string_length + 1, allocator.state);
  if (NULL == new_string) {
    RCUTILS_SET_ERROR_MSG("failed to allocate memory for new string");
    return NULL;
  }

  char * pos = new_string;
  for (size_t i = 0; i < string_array->size; i++) {
    if (i != 0) {
      memcpy(pos, separator, sep_length);
      pos += sep_length;
    }
    if (string_array->data[i]) {
      string_length = strlen(string_array->data[i]);
      memcpy(pos, string_array->data[i], string_length);
      pos += string_length;
    }
  }

  *pos = '\0';

  return new_string;
}

