static void create_format_string(
  const char * logging_output_format_string)
{
  size_t dest_buffer_index = 0;
  size_t start_offset = 0;
  size_t start_offset_previous_not_copy = 0;
  size_t back_slash_index = 0;

  size_t length = strlen(logging_output_format_string);
  if (length > RCUTILS_LOGGING_MAX_OUTPUT_FORMAT_LEN - 1) {
    length = RCUTILS_LOGGING_MAX_OUTPUT_FORMAT_LEN - 1;
  }

  for (size_t i = 0; i < length; ) {
    back_slash_index = rcutils_findn(
      logging_output_format_string + i, RCUTILS_LOGGING_BACKSLASH_CHAR, length - i);
    if (back_slash_index == SIZE_MAX) {
      memcpy(
        g_rcutils_logging_output_format_string + dest_buffer_index,
        logging_output_format_string + start_offset - start_offset_previous_not_copy,
        length - start_offset + start_offset_previous_not_copy);
      break;
    } else {
      const char * expected_char = NULL;
      int skip_chars = 0;

      if (logging_output_format_string[i + back_slash_index + 1] == 'x' &&
        logging_output_format_string[i + back_slash_index + 2] == '1' &&
        logging_output_format_string[i + back_slash_index + 3] == 'b')
      {
        // detect escape sequence
        ACTIVATE_VIRTUAL_TERMINAL_PROCESSING();
        expected_char = "\x1b";
        // the 4 char long "\x1b" string literal will become a 2 char long \x1b escape sequence
        // therefore we need to skip forward in parsing the output format string
        skip_chars = 2;
      } else {
        switch (logging_output_format_string[i + back_slash_index + 1]) {
          case 'a':  expected_char = "\a"; break;  // alert
          case 'b':  expected_char = "\b"; break;  // backspace
          case 'n':  expected_char = "\n"; break;  // new line
          case 'r':  expected_char = "\r"; break;  // carriage return
          case 't':  expected_char = "\t"; break;  // horizontal tab
          default:
            break;
        }
      }

      if (expected_char) {
        if (back_slash_index > 0) {
          // copy previous buffer first
          size_t len = back_slash_index + start_offset_previous_not_copy;
          memcpy(
            g_rcutils_logging_output_format_string + dest_buffer_index,
            logging_output_format_string + start_offset,
            len);
          dest_buffer_index += len;
          start_offset += len;
          start_offset_previous_not_copy = 0;
        }

        // copy the decoded character
        g_rcutils_logging_output_format_string[dest_buffer_index] = expected_char[0];
        dest_buffer_index += 1;
        start_offset += 2 + skip_chars;
      } else {
        start_offset_previous_not_copy += (back_slash_index + 2);
      }

      i += (back_slash_index + 2 + skip_chars);
    }
  }
}

static bool add_handler(token_handler handler, size_t start_offset, size_t end_offset)
{
  if (g_num_log_msg_handlers >= (sizeof(g_handlers) / sizeof(g_handlers[0]))) {
    RCUTILS_SET_ERROR_MSG("Too many substitutions in the logging output format string; truncating");
    return false;
  }

  g_handlers[g_num_log_msg_handlers].handler = handler;
  g_handlers[g_num_log_msg_handlers].start_offset = start_offset;
  g_handlers[g_num_log_msg_handlers].end_offset = end_offset;

  g_num_log_msg_handlers++;

  return true;
}

static void parse_and_create_handlers_list(void)
{
  // Process the format string looking for known tokens.
  const char token_start_delimiter = '{';
  const char token_end_delimiter = '}';

  const char * str = g_rcutils_logging_output_format_string;
  size_t size = strlen(g_rcutils_logging_output_format_string);

  g_num_log_msg_handlers = 0;

  // Walk through the format string and create callbacks when they're encountered.
  size_t i = 0;
  while (i < size) {
    // Print everything up to the next token start delimiter.
    size_t chars_to_start_delim = rcutils_find(str + i, token_start_delimiter);
    size_t remaining_chars = size - i;

    if (chars_to_start_delim > 0) {  // there is stuff before a token start delimiter
      size_t chars_to_copy = chars_to_start_delim >
        remaining_chars ? remaining_chars : chars_to_start_delim;
      if (!add_handler(copy_from_orig, i, i + chars_to_copy)) {
        // The error was already set by add_handler
        return;
      }

      i += chars_to_copy;
      if (i >= size) {  // perhaps no start delimiter was found
        break;
      }

      continue;
    }

    // We are at a token start delimiter: determine if there's a known token or not.
    // Potential tokens can't possibly be longer than the format string itself.
    char token[RCUTILS_LOGGING_MAX_OUTPUT_FORMAT_LEN];

    // Look for a token end delimiter.
    size_t chars_to_end_delim = rcutils_find(str + i, token_end_delimiter);
    remaining_chars = size - i;

    if (chars_to_end_delim > remaining_chars) {
      // No end delimiters found in the remainder of the format string;
      // there won't be any more tokens so shortcut the rest of the checking.
      if (!add_handler(copy_from_orig, i, i + remaining_chars)) {
        // The error was already set by add_handler
        return;
      }
      break;
    }

    // Found what looks like a token; determine if it's recognized.
    size_t token_len = chars_to_end_delim - 1;  // Not including delimiters.
    memcpy(token, str + i + 1, token_len);  // Skip the start delimiter.
    token[token_len] = '\0';

    token_handler expand_token = find_token_handler(token);

    if (!expand_token) {
      // This wasn't a token; print the start delimiter and continue the search as usual
      // (the substring might contain more start delimiters).
      if (!add_handler(copy_from_orig, i, i + 1)) {
        // The error was already set by add_handler
        return;
      }
      i++;
      continue;
    }

    if (!add_handler(expand_token, 0, 0)) {
      // The error was already set by add_handler
      return;
    }

    // Skip ahead to avoid re-processing the token characters (including the 2 delimiters).
    i += token_len + 2;
  }
}

rcutils_ret_t rcutils_logging_allocator_initialize(
  const rcutils_allocator_t * allocator)
{
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    allocator, "invalid allocator", return RCUTILS_RET_INVALID_ARGUMENT);

  if (rcutils_allocator_is_valid(&g_rcutils_logging_allocator)) {
    return RCUTILS_RET_OK;
  }
  g_rcutils_logging_allocator = *allocator;

  return RCUTILS_RET_OK;
}

rcutils_ret_t rcutils_logging_initialize_with_allocator(rcutils_allocator_t allocator)
{
  if (g_rcutils_logging_initialized) {
    return RCUTILS_RET_OK;
  }

  if (rcutils_logging_allocator_initialize(&allocator) != RCUTILS_RET_OK) {
    return RCUTILS_RET_INVALID_ARGUMENT;
  }

  g_rcutils_logging_output_handler = &rcutils_logging_console_output_handler;
  // Check for the environment variable for default logger level
  const char * env_default_level;
  const char * ret_str_level =
    rcutils_get_env("RCUTILS_DEFAULT_LOGGER_DEFAULT_LEVEL", &env_default_level);
  if (NULL != ret_str_level) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "Error getting environment variable RCUTILS_DEFAULT_LOGGER_DEFAULT_LEVEL: %s", ret_str_level);
    g_rcutils_logging_default_logger_level = RCUTILS_DEFAULT_LOGGER_DEFAULT_LEVEL;
  } else if (strcmp(env_default_level, "") == 0) {
    // Environment variable is empty, use default
    g_rcutils_logging_default_logger_level = RCUTILS_DEFAULT_LOGGER_DEFAULT_LEVEL;
  } else {
    // Try to convert the environment variable value to a severity level
    int env_severity;
    rcutils_ret_t severity_ret = rcutils_logging_severity_level_from_string(
      env_default_level, g_rcutils_logging_allocator, &env_severity);
    if (severity_ret == RCUTILS_RET_OK) {
      g_rcutils_logging_default_logger_level = env_severity;
    } else {
      RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
        "Invalid severity level '%s' in RCUTILS_DEFAULT_LOGGER_DEFAULT_LEVEL. Using default.",
        env_default_level);
      g_rcutils_logging_default_logger_level = RCUTILS_DEFAULT_LOGGER_DEFAULT_LEVEL;
    }
  }

  const char * line_buffered = NULL;
  const char * ret_str = rcutils_get_env("RCUTILS_CONSOLE_STDOUT_LINE_BUFFERED", &line_buffered);
  if (NULL != ret_str) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "Error getting environment variable RCUTILS_CONSOLE_STDOUT_LINE_BUFFERED: %s", ret_str);
    return RCUTILS_RET_ERROR;
  }

  if (strcmp(line_buffered, "") != 0) {
    RCUTILS_SAFE_FWRITE_TO_STDERR(
      "RCUTILS_CONSOLE_STDOUT_LINE_BUFFERED is now ignored. "
      "Please set RCUTILS_LOGGING_USE_STDOUT and RCUTILS_LOGGING_BUFFERED_STREAM "
      "to control the stream and the buffering of log messages.\n");
  }

  // Set the default output stream for all severities to stderr so that errors
  // are propagated immediately.
  // The user can choose to set the output stream to stdout by setting the
  // RCUTILS_LOGGING_USE_STDOUT environment variable to 1.
  enum rcutils_get_env_retval retval = rcutils_get_env_var_zero_or_one(
    "RCUTILS_LOGGING_USE_STDOUT", "use stderr", "use stdout");
  switch (retval) {
    case RCUTILS_GET_ENV_ERROR:
      return RCUTILS_RET_INVALID_ARGUMENT;
    case RCUTILS_GET_ENV_EMPTY:
    case RCUTILS_GET_ENV_ZERO:
      g_output_stream = stderr;
      break;
    case RCUTILS_GET_ENV_ONE:
      g_output_stream = stdout;
      break;
  }

  // Allow the user to choose how buffering on the stream works by setting
  // RCUTILS_LOGGING_BUFFERED_STREAM.
  // With an empty environment variable, use the default of the stream.
  // With a value of 0, force the stream to be unbuffered.
  // With a value of 1, force the stream to be line buffered.
  retval = rcutils_get_env_var_zero_or_one(
    "RCUTILS_LOGGING_BUFFERED_STREAM", "not buffered", "buffered");
  if (RCUTILS_GET_ENV_ERROR == retval) {
    return RCUTILS_RET_INVALID_ARGUMENT;
  }
  if (RCUTILS_GET_ENV_ZERO == retval || RCUTILS_GET_ENV_ONE == retval) {
    int mode = retval == RCUTILS_GET_ENV_ZERO ? _IONBF : _IOLBF;
    size_t buffer_size = (mode == _IOLBF) ? RCUTILS_LOGGING_STREAM_BUFFER_SIZE : 0;

    // buffer_size cannot be 0 on Windows with IOLBF, see comments above where it's #define'd
    if (setvbuf(g_output_stream, NULL, mode, buffer_size) != 0) {
      char error_string[1024];
      rcutils_strerror(error_string, sizeof(error_string));
      RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
        "Error setting stream buffering mode: %s", error_string);
      return RCUTILS_RET_ERROR;
    }
  } else if (RCUTILS_GET_ENV_EMPTY != retval) {
    RCUTILS_SET_ERROR_MSG(
      "Invalid return from environment fetch");
    return RCUTILS_RET_ERROR;
  }

  retval = rcutils_get_env_var_zero_or_one(
    "RCUTILS_COLORIZED_OUTPUT", "force color",
    "force no color");
  switch (retval) {
    case RCUTILS_GET_ENV_ERROR:
      return RCUTILS_RET_INVALID_ARGUMENT;
    case RCUTILS_GET_ENV_EMPTY:
      g_colorized_output = RCUTILS_COLORIZED_OUTPUT_AUTO;
      break;
    case RCUTILS_GET_ENV_ZERO:
      g_colorized_output = RCUTILS_COLORIZED_OUTPUT_FORCE_DISABLE;
      break;
    case RCUTILS_GET_ENV_ONE:
      g_colorized_output = RCUTILS_COLORIZED_OUTPUT_FORCE_ENABLE;
      break;
  }

  // Check for the environment variable for custom output formatting
  const char * output_format;
  ret_str = rcutils_get_env("RCUTILS_CONSOLE_OUTPUT_FORMAT", &output_format);
  if (NULL != ret_str) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "Failed to get output format from env. variable [%s]. Using default output format.",
      ret_str);
    output_format = g_rcutils_logging_default_output_format;
  } else {
    if (strcmp(output_format, "") == 0) {
      output_format = g_rcutils_logging_default_output_format;
    }
  }

  create_format_string(output_format);

  g_rcutils_logging_severities_map = rcutils_get_zero_initialized_hash_map();
  rcutils_ret_t hash_map_ret = rcutils_hash_map_init(
    &g_rcutils_logging_severities_map, 2, sizeof(const char *), sizeof(int),
    rcutils_hash_map_string_hash_func, rcutils_hash_map_string_cmp_func, &allocator);
  if (hash_map_ret != RCUTILS_RET_OK) {
    rcutils_reset_error();
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "Failed to initialize map for logger severities [%s]. Severities will not be configurable.",
      rcutils_get_error_string().str);
    g_rcutils_logging_severities_map_valid = false;
    return RCUTILS_RET_ERROR;
  }

  parse_and_create_handlers_list();

  g_rcutils_logging_severities_map_valid = true;

  g_rcutils_logging_initialized = true;

  return RCUTILS_RET_OK;
}

rcutils_ret_t rcutils_logging_shutdown(void)
{
  if (!g_rcutils_logging_initialized) {
    return RCUTILS_RET_OK;
  }

  rcutils_ret_t ret = RCUTILS_RET_OK;
  if (g_rcutils_logging_severities_map_valid) {
    // Iterate over the map, getting every key so we can free it
    char * key = NULL;
    int level;
    rcutils_ret_t hash_map_ret = rcutils_hash_map_get_next_key_and_data(
      &g_rcutils_logging_severities_map, NULL, &key, &level);
    while (RCUTILS_RET_OK == hash_map_ret) {
      hash_map_ret = rcutils_hash_map_unset(&g_rcutils_logging_severities_map, &key);
      if (hash_map_ret != RCUTILS_RET_OK) {
        RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
          "Failed to clear out logger severities [%s] during shutdown; memory will be leaked.",
          rcutils_get_error_string().str);
        break;
      }
      g_rcutils_logging_allocator.deallocate(key, g_rcutils_logging_allocator.state);

      hash_map_ret = rcutils_hash_map_get_next_key_and_data(
        &g_rcutils_logging_severities_map, NULL, &key, &level);
    }

    hash_map_ret = rcutils_hash_map_fini(&g_rcutils_logging_severities_map);
    if (hash_map_ret != RCUTILS_RET_OK) {
      RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
        "Failed to finalize map for logger severities: %s",
        rcutils_get_error_string().str);
      ret = RCUTILS_RET_LOGGING_SEVERITY_MAP_INVALID;
    }
    g_rcutils_logging_severities_map_valid = false;
  }
  g_num_log_msg_handlers = 0;
  g_rcutils_logging_allocator = rcutils_get_zero_initialized_allocator();
  g_rcutils_logging_initialized = false;

  #ifdef _WIN32
  if (g_consol_mode_modified) {
    SetConsoleMode(GetStdHandle(STD_ERROR_HANDLE), g_original_console_mode);
  }
  #endif
  return ret;
}

rcutils_ret_t
rcutils_logging_severity_level_from_string(
  const char * severity_string, rcutils_allocator_t allocator, int * severity)
{
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    &allocator, "invalid allocator", return RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(severity_string, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(severity, RCUTILS_RET_INVALID_ARGUMENT);

  rcutils_ret_t ret = RCUTILS_RET_LOGGING_SEVERITY_STRING_INVALID;

  // Convert the input string to upper case (for case insensitivity).
  char * severity_string_upper = rcutils_strdup(severity_string, allocator);
  if (NULL == severity_string_upper) {
    RCUTILS_SET_ERROR_MSG("failed to allocate memory for uppercase string");
    return RCUTILS_RET_BAD_ALLOC;
  }
  for (int i = 0; severity_string_upper[i]; ++i) {
    severity_string_upper[i] = (char)toupper(severity_string_upper[i]);
  }

  // Determine the severity value matching the severity name.
  for (size_t i = 0;
    i < sizeof(g_rcutils_log_severity_names) / sizeof(g_rcutils_log_severity_names[0]);
    ++i)
  {
    const char * severity_string_i = g_rcutils_log_severity_names[i];
    if (severity_string_i && strcmp(severity_string_i, severity_string_upper) == 0) {
      *severity = (enum RCUTILS_LOG_SEVERITY)i;
      ret = RCUTILS_RET_OK;
      break;
    }
  }
  allocator.deallocate(severity_string_upper, allocator.state);
  return ret;
}

rcutils_logging_output_handler_t rcutils_logging_get_output_handler(void)
{
  RCUTILS_LOGGING_AUTOINIT;
  return g_rcutils_logging_output_handler;
}

void rcutils_logging_set_output_handler(rcutils_logging_output_handler_t function)
{
  RCUTILS_LOGGING_AUTOINIT;
  g_rcutils_logging_output_handler = function;
}

int rcutils_logging_get_default_logger_level(void)
{
  RCUTILS_LOGGING_AUTOINIT;
  return g_rcutils_logging_default_logger_level;
}

void rcutils_logging_set_default_logger_level(int level)
{
  RCUTILS_LOGGING_AUTOINIT;
  if (RCUTILS_LOG_SEVERITY_UNSET == level) {
    // Restore the default
    level = RCUTILS_DEFAULT_LOGGER_DEFAULT_LEVEL;
  }
  g_rcutils_logging_default_logger_level = level;
}

int rcutils_logging_get_logger_level(const char * name)
{
  RCUTILS_LOGGING_AUTOINIT;
  if (NULL == name) {
    return -1;
  }
  return rcutils_logging_get_logger_leveln(name, strlen(name));
}

static rcutils_ret_t add_key_to_hash_map(const char * name, int level, bool set_by_user)
{
  const char * copy_name = name;
  // Check if key already exists, to avoid extra memory allocation
  // If the key already exists, then rcutils_hash_map_set will not maintain the key we give it,
  // so we do not need to copy the name
  bool already_exists = rcutils_hash_map_key_exists(&g_rcutils_logging_severities_map, &copy_name);

  if (!already_exists) {
    // Copy the name to be stored, as there is no guarantee that the caller will keep it around.
    copy_name = rcutils_strdup(name, g_rcutils_logging_allocator);
    if (copy_name == NULL) {
      // Don't report an error to the error handling machinery; some uses of this function are for
      // caching so this is not necessarily fatal.
      return RCUTILS_RET_ERROR;
    }
  }

  if (set_by_user) {
    // If the level was set by the user (rather than optimistically cached by the implementation),
    // mark it here.  When we purge the cache, we'll make sure not to purge these.  The mark we
    // use is setting the bottom bit; since our levels are 0, 10, 20, 30, 40, and 50, this works.
    level |= 0x1;
  }

  rcutils_ret_t hash_map_ret =
    rcutils_hash_map_set(&g_rcutils_logging_severities_map, &copy_name, &level);
  if (hash_map_ret != RCUTILS_RET_OK) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "Error setting severity level for logger named '%s': %s",
      name, rcutils_get_error_string().str);
    return RCUTILS_RET_ERROR;
  }

  return RCUTILS_RET_OK;
}

static rcutils_ret_t get_severity_level(const char * name, int * severity)
{
  rcutils_ret_t ret =
    rcutils_hash_map_get(&g_rcutils_logging_severities_map, &name, severity);
  if (ret != RCUTILS_RET_OK) {
    // One possible response is RCUTILS_RET_NOT_FOUND, but the higher layers may be OK with that.
    return ret;
  }

  // See the comment in add_key_to_hash_map() on why we remove the bottom bit.
  (*severity) &= ~(0x1);

  return RCUTILS_RET_OK;
}

int rcutils_logging_get_logger_leveln(const char * name, size_t name_length)
{
  RCUTILS_LOGGING_AUTOINIT;
  if (NULL == name) {
    return -1;
  }

  // Skip the map lookup if the default was requested,
  // as it can still be used even if the severity map is invalid.
  if (0 == name_length) {
    return g_rcutils_logging_default_logger_level;
  }
  if (!g_rcutils_logging_severities_map_valid) {
    return RCUTILS_LOG_SEVERITY_UNSET;
  }

  char * short_name = rcutils_strndup(name, name_length, g_rcutils_logging_allocator);
  if (short_name == NULL) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "Failed to allocate memory when looking up logger level for '%s'", name);
    return -1;
  }

  int severity;
  rcutils_ret_t ret = get_severity_level(short_name, &severity);
  g_rcutils_logging_allocator.deallocate(short_name, g_rcutils_logging_allocator.state);
  if (ret != RCUTILS_RET_OK) {
    // The error message was already set by get_severity_level
    return RCUTILS_LOG_SEVERITY_UNSET;
  }

  return severity;
}

int rcutils_logging_get_logger_effective_level(const char * name)
{
  RCUTILS_LOGGING_AUTOINIT;
  if (NULL == name) {
    return -1;
  }

  size_t hash_map_size;
  rcutils_ret_t hash_map_ret = rcutils_hash_map_get_size(
    &g_rcutils_logging_severities_map, &hash_map_size);
  if (hash_map_ret != RCUTILS_RET_OK) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "Error getting severity level for logger named '%s': %s",
      name, rcutils_get_error_string().str);
    return -1;
  }

  if (hash_map_size == 0) {
    // The reason we do this extra check here is a bit tricky.  The call to get_severity_level()
    // below calls rcutils_hash_map_get(), which already has an optimization to return early if
    // there are no entries in the map.  However, the rest of this function doesn't know how to
    // disambiguate between not finding this particular name in the map and there being no items in
    // the map.  In the former case, we need to do the additional work of looking through the
    // hierarchy of loggers, while in the latter case we can short-circuit.  To keep this function
    // fast in the latter case, we do the disambiguation here.
    return g_rcutils_logging_default_logger_level;
  }

  // Start by trying to find the exact name.
  int severity;
  rcutils_ret_t ret = get_severity_level(name, &severity);
  if (ret == RCUTILS_RET_OK) {
    if (severity != RCUTILS_LOG_SEVERITY_UNSET) {
      return severity;
    }
    // If the severity is UNSET, then we go through the slow path and try to find a parent logger
    // that is set.  Failing that, we fall back to the default logger level.
  } else if (ret != RCUTILS_RET_NOT_FOUND) {
    // The error message was already set by get_severity_level
    return -1;
  }

  // Since we didn't find the name in the fast path, fall back to the slow path where we break the
  // string into substrings based on dots and look for any part that matches.

  size_t substring_length = strlen(name);
  char * tmp_name = rcutils_strdup(name, g_rcutils_logging_allocator);
  if (tmp_name == NULL) {
    RCUTILS_SAFE_FWRITE_TO_STDERR_WITH_FORMAT_STRING(
      "Error copying string '%s'\n", name);
    return -1;
  }

  severity = RCUTILS_LOG_SEVERITY_UNSET;

  while (true) {
    // Determine the next ancestor's FQN by removing the child's name.
    size_t index_last_separator = rcutils_find_lastn(
      name, RCUTILS_LOGGING_SEPARATOR_CHAR, substring_length);
    if (SIZE_MAX == index_last_separator) {
      // There are no more separators in the substring, so this is the last name we needed to check.
      break;
    }

    substring_length = index_last_separator;

    // Shorten the substring to be the name of the ancestor (excluding the separator).
    tmp_name[index_last_separator] = '\0';

    rcutils_ret_t ret = get_severity_level(tmp_name, &severity);
    if (ret == RCUTILS_RET_OK) {
      if (severity != RCUTILS_LOG_SEVERITY_UNSET) {
        break;
      }
    } else if (ret != RCUTILS_RET_NOT_FOUND) {
      // The error message was already set by get_severity_level
      g_rcutils_logging_allocator.deallocate(tmp_name, g_rcutils_logging_allocator.state);
      return -1;
    }
  }

  g_rcutils_logging_allocator.deallocate(tmp_name, g_rcutils_logging_allocator.state);

  if (severity == RCUTILS_LOG_SEVERITY_UNSET) {
    // Neither the logger nor its ancestors have had their level specified.
    severity = g_rcutils_logging_default_logger_level;
  }

  // TODO(wjwwood): restore or replace this optimization when thread-safety is addressed
  //   see: https://github.com/ros2/rcutils/pull/393
  // // If the calculated severity is anything but UNSET, we place it into the hashmap for speedier
  // // lookup next time.  If the severity is UNSET, we don't bother because we are going to have to
  // // walk the hierarchy next time anyway.
  // if (severity != RCUTILS_LOG_SEVERITY_UNSET) {
  //   ret = add_key_to_hash_map(name, severity, false);
  //   if (ret != RCUTILS_RET_OK) {
  //     // Continue on if we failed to add the key to the hashmap.
  //     // This will affect performance but is not fatal.
  //     RCUTILS_SAFE_FWRITE_TO_STDERR(
  //       "Failed to cache severity; this is not fatal but will impact performance\n");
  //   }
  // }

  return severity;
}

rcutils_ret_t rcutils_logging_set_logger_level(const char * name, int level)
{
  RCUTILS_LOGGING_AUTOINIT;
  if (NULL == name) {
    RCUTILS_SET_ERROR_MSG("Invalid logger name");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }

  if (!g_rcutils_logging_severities_map_valid) {
    RCUTILS_SET_ERROR_MSG("Logger severity level map is invalid");
    return RCUTILS_RET_LOGGING_SEVERITY_MAP_INVALID;
  }

  // Convert the severity value into a string for storage.
  if (level < 0 ||
    level >=
    (int)(sizeof(g_rcutils_log_severity_names) / sizeof(g_rcutils_log_severity_names[0])))
  {
    RCUTILS_SET_ERROR_MSG("Invalid severity level specified for logger");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }
  const char * severity_string = g_rcutils_log_severity_names[level];
  if (NULL == severity_string) {
    RCUTILS_SET_ERROR_MSG("Unable to determine severity_string for severity");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }

  size_t name_length = strlen(name);

  if (rcutils_hash_map_key_exists(&g_rcutils_logging_severities_map, &name)) {
    // Iterate over the entire contents of the severities map, looking for entries that start with
    // this key name.  For any ones that match, check whether the user explicitly set them.  If the
    // user did not set it, then we cached it and so we can throw it away.

    char * key = NULL;
    int tmp_level;

    rcutils_ret_t hash_map_ret = rcutils_hash_map_get_next_key_and_data(
      &g_rcutils_logging_severities_map, NULL, &key, &tmp_level);
    while (RCUTILS_RET_OK == hash_map_ret) {
      // Hold onto a reference to the pointer; we'll need it later
      char * previous_key = key;
      bool free_current_key = false;
      if (key != NULL && strncmp(name, key, name_length) == 0) {
        // If this is the key we are replacing, unconditionally remove it from the hash map;
        // we'll be adding it back as a user-set level anyway
        if (key[name_length] == '\0') {
          free_current_key = true;
        } else {
          // Otherwise, this is a descendant; only remove it from the hash map
          // if we cached it (the user didn't explicitly set it).
          if (!(tmp_level & 0x1)) {
            free_current_key = true;
          }
        }
      }

      // Note that we need to get the next key before we free the current
      // key so that we can continue iterating over the hash_map
      hash_map_ret = rcutils_hash_map_get_next_key_and_data(
        &g_rcutils_logging_severities_map, &previous_key, &key, &tmp_level);
      if (hash_map_ret != RCUTILS_RET_OK &&
        hash_map_ret != RCUTILS_RET_HASH_MAP_NO_MORE_ENTRIES &&
        hash_map_ret != RCUTILS_RET_NOT_FOUND)
      {
        RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
          "Error accessing hash map when setting logger level for '%s': %s",
          name, rcutils_get_error_string().str);
        return hash_map_ret;
      }

      if (free_current_key) {
        rcutils_ret_t unset_ret = rcutils_hash_map_unset(
          &g_rcutils_logging_severities_map, &previous_key);
        if (unset_ret != RCUTILS_RET_OK) {
          // The only way that hash_map_unset can fail is if there is something wrong with the
          // hashmap structure or the key is NULL.  Since we don't expect either, report it as an
          // error and return.
          RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
            "Error clearing old severity level for logger named '%s': %s",
            name, rcutils_get_error_string().str);
          return unset_ret;
        }
        g_rcutils_logging_allocator.deallocate(previous_key, g_rcutils_logging_allocator.state);
      }
    }
  }

  rcutils_ret_t add_key_ret = add_key_to_hash_map(name, level, true);
  if (add_key_ret != RCUTILS_RET_OK) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "Error setting severity level for logger named '%s': %s",
      name, rcutils_get_error_string().str);
  }

  if (name_length == 0) {
    // If the name was empty, this also means we should update the default logger level
    g_rcutils_logging_default_logger_level = level;
  }

  return add_key_ret;
}

bool rcutils_logging_logger_is_enabled_for(const char * name, int severity)
{
  RCUTILS_LOGGING_AUTOINIT;
  int logger_level = g_rcutils_logging_default_logger_level;
  if (name) {
    logger_level = rcutils_logging_get_logger_effective_level(name);
    if (-1 == logger_level) {
      RCUTILS_SAFE_FWRITE_TO_STDERR_WITH_FORMAT_STRING(
        "Error determining if logger '%s' is enabled for severity '%d'\n",
        name, severity);
      return false;
    }
  }
  return severity >= logger_level;
}

static void vrcutils_log_internal(
  const rcutils_log_location_t * location,
  int severity, const char * name, const char * format, va_list * args)
{
  rcutils_time_point_value_t now;
  rcutils_ret_t ret = rcutils_system_time_now(&now);
  if (ret != RCUTILS_RET_OK) {
    RCUTILS_SAFE_FWRITE_TO_STDERR("Failed to get timestamp while doing a console logging.\n");
    return;
  }
  rcutils_logging_output_handler_t output_handler = g_rcutils_logging_output_handler;
  if (output_handler != NULL) {
    (*output_handler)(location, severity, name ? name : "", now, format, args);
  }
}

void rcutils_log(
  const rcutils_log_location_t * location,
  int severity, const char * name, const char * format, ...)
{
  if (!rcutils_logging_logger_is_enabled_for(name, severity)) {
    return;
  }

  va_list args;
  va_start(args, format);
  vrcutils_log_internal(location, severity, name, format, &args);
  va_end(args);
}

void rcutils_log_internal(
  const rcutils_log_location_t * location,
  int severity, const char * name, const char * format, ...)
{
  va_list args;
  va_start(args, format);
  vrcutils_log_internal(location, severity, name, format, &args);
  va_end(args);
}

rcutils_ret_t rcutils_logging_format_message(
  const rcutils_log_location_t * location,
  int severity, const char * name, rcutils_time_point_value_t timestamp,
  const char * msg, rcutils_char_array_t * logging_output)
{
  const logging_input_t logging_input = {
    .location = location,
    .severity = severity,
    .name = name,
    .timestamp = timestamp,
    .msg = msg
  };

  for (size_t i = 0; i < g_num_log_msg_handlers; ++i) {
    if (g_handlers[i].handler(
        &logging_input, logging_output,
        g_handlers[i].start_offset, g_handlers[i].end_offset) == NULL)
    {
      return RCUTILS_RET_ERROR;
    }
  }

  return RCUTILS_RET_OK;
}

void rcutils_logging_console_output_handler(
  const rcutils_log_location_t * location,
  int severity, const char * name, rcutils_time_point_value_t timestamp,
  const char * format, va_list * args)
{
  rcutils_ret_t status = RCUTILS_RET_OK;
  bool is_colorized = false;

  if (!g_rcutils_logging_initialized) {
    RCUTILS_SAFE_FWRITE_TO_STDERR(
      "logging system isn't initialized: "
      "call to rcutils_logging_console_output_handler failed.\n");
    return;
  }
  switch (severity) {
    case RCUTILS_LOG_SEVERITY_DEBUG:
    case RCUTILS_LOG_SEVERITY_INFO:
    case RCUTILS_LOG_SEVERITY_WARN:
    case RCUTILS_LOG_SEVERITY_ERROR:
    case RCUTILS_LOG_SEVERITY_FATAL:
      break;
    default:
      RCUTILS_SAFE_FWRITE_TO_STDERR_WITH_FORMAT_STRING(
        "unknown severity level: %d\n", severity);
      return;
  }

  if (g_colorized_output == RCUTILS_COLORIZED_OUTPUT_FORCE_ENABLE) {
    is_colorized = true;
  } else if (g_colorized_output == RCUTILS_COLORIZED_OUTPUT_FORCE_DISABLE) {
    is_colorized = false;
  } else {
    is_colorized = IS_STREAM_A_TTY(g_output_stream);
  }

  char msg_buf[1024] = "";
  rcutils_char_array_t msg_array = {
    .buffer = msg_buf,
    .owns_buffer = false,
    .buffer_length = 0u,
    .buffer_capacity = sizeof(msg_buf),
    .allocator = g_rcutils_logging_allocator
  };

  char output_buf[1024] = "";
  rcutils_char_array_t output_array = {
    .buffer = output_buf,
    .owns_buffer = false,
    .buffer_length = 0u,
    .buffer_capacity = sizeof(output_buf),
    .allocator = g_rcutils_logging_allocator
  };

  if (is_colorized) {
    SET_OUTPUT_COLOR_WITH_SEVERITY(status, severity, output_array)
  }

  if (RCUTILS_RET_OK == status) {
    status = rcutils_char_array_vsprintf(&msg_array, format, *args);
    if (RCUTILS_RET_OK != status) {
      RCUTILS_SAFE_FWRITE_TO_STDERR_WITH_FORMAT_STRING(
        "Error: rcutils_char_array_vsprintf failed with: %d\n", status);
    }
  }

  if (RCUTILS_RET_OK == status) {
    status = rcutils_logging_format_message(
      location, severity, name, timestamp, msg_array.buffer, &output_array);
    if (RCUTILS_RET_OK != status) {
      RCUTILS_SAFE_FWRITE_TO_STDERR_WITH_FORMAT_STRING(
        "Error: rcutils_logging_format_message failed with: %d\n", status);
    }
  }

  // Does nothing in windows
  SET_STANDARD_COLOR_IN_BUFFER(is_colorized, status, output_array)

  if (RCUTILS_RET_OK == status) {
    fprintf(g_output_stream, "%s\n", output_array.buffer);
  }

  // Only does something in windows
  // cppcheck-suppress uninitvar  // suppress cppcheck false positive
  SET_STANDARD_COLOR_IN_STREAM(is_colorized, status)

  status = rcutils_char_array_fini(&msg_array);
  if (RCUTILS_RET_OK != status) {
    RCUTILS_SAFE_FWRITE_TO_STDERR("Failed to fini array.\n");
  }
  status = rcutils_char_array_fini(&output_array);
  if (RCUTILS_RET_OK != status) {
    RCUTILS_SAFE_FWRITE_TO_STDERR("Failed to fini array.\n");
  }
}

int rcutils_get_pid(void)
{
#if defined _WIN32 || defined __CYGWIN__
  return (int)GetCurrentProcessId();
#else
  return (int)getpid();
#endif
}

char * rcutils_get_executable_name(rcutils_allocator_t allocator)
{
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    &allocator, "invalid allocator", return NULL);

#if defined __APPLE__ || defined __FreeBSD__ || (defined __ANDROID__ && __ANDROID_API__ >= 21)
  const char * appname = getprogname();
#elif (defined __GNUC__ && !defined(__MINGW64__)) && !defined(__QNXNTO__) && !defined(__OHOS__)
  const char * appname = program_invocation_name;
#elif defined _WIN32 || defined __CYGWIN__
  char appname[MAX_PATH];
  int32_t size = GetModuleFileNameA(NULL, appname, MAX_PATH);
  if (size == 0) {
    return NULL;
  }
#elif defined __QNXNTO__ || defined __OHOS__
  extern char * __progname;
  const char * appname = __progname;
#else
#error "Unsupported OS"
#endif

  size_t applen = strlen(appname);

  // Since the above memory may be static, and the caller may want to modify
  // the argument, make and return a copy here.
  char * executable_name = allocator.allocate(applen + 1, allocator.state);
  if (NULL == executable_name) {
    return NULL;
  }

  // Get just the executable name (Unix may return the absolute path)
#if defined __APPLE__ || defined __FreeBSD__ || (defined __GNUC__ && !defined(__MINGW64__))
  // We need an intermediate copy because basename may modify its arguments
  char * intermediate = rcutils_strdup(appname, allocator);
  if (NULL == intermediate) {
    allocator.deallocate(executable_name, allocator.state);
    return NULL;
  }

  char * bname = basename(intermediate);
  size_t baselen = strlen(bname);
  memcpy(executable_name, bname, baselen);
  executable_name[baselen] = '\0';
  allocator.deallocate(intermediate, allocator.state);
#elif defined _WIN32 || defined __CYGWIN__
  errno_t err = _splitpath_s(appname, NULL, 0, NULL, 0, executable_name, applen, NULL, 0);
  if (err != 0) {
    allocator.deallocate(executable_name, allocator.state);
    return NULL;
  }
#else
#error "Unsupported OS"
#endif

  return executable_name;
}

static
rcutils_ret_t
append_backslashes(rcutils_char_array_t * char_array, size_t num_backslashes)
{
  if (num_backslashes <= 0) {
    return RCUTILS_RET_OK;
  }

  size_t current_strlen;
  if (char_array->buffer_length == 0) {
    current_strlen = 0;
  } else {
    // The buffer length always contains the trailing \0, so the strlen is one less than that.
    current_strlen = char_array->buffer_length - 1;
  }

  size_t new_length = current_strlen + num_backslashes + 1;
  rcutils_ret_t ret = rcutils_char_array_expand_as_needed(char_array, new_length);
  if (RCUTILS_RET_OK != ret) {
    return ret;
  }

  memset(char_array->buffer + current_strlen, '\\', num_backslashes);
  char_array->buffer[new_length - 1] = '\0';

  char_array->buffer_length = new_length;

  return RCUTILS_RET_OK;
}

static
rcutils_ret_t
build_command_line(
  const rcutils_string_array_t * string_array,
  rcutils_char_array_t * char_array)
{
  rcutils_ret_t ret;

  for (size_t i = 0; i < string_array->size; i++) {
    // Append argument separator
    if (i != 0) {
      ret = rcutils_char_array_strncat(char_array, " ", 1);
      if (RCUTILS_RET_OK != ret) {
        return ret;
      }
    }

    // Append argument which doesn't need to be quoted
    size_t arg_length = strlen(string_array->data[i]);
    if (strcspn(string_array->data[i], " \t\n\v\"") >= arg_length) {
      ret = rcutils_char_array_strncat(char_array, string_array->data[i], arg_length);
      if (RCUTILS_RET_OK != ret) {
        return ret;
      }
      continue;
    }

    // Append opening quote
    ret = rcutils_char_array_strncat(char_array, "\"", 1);
    if (RCUTILS_RET_OK != ret) {
      return ret;
    }

    for (const char * c = string_array->data[i]; ; c++) {
      size_t backslash_count = 0;
      while ('\\' == *c) {
        backslash_count++;
        c++;
      }

      if ('\0' == *c) {
        ret = append_backslashes(char_array, backslash_count * 2);
        if (RCUTILS_RET_OK != ret) {
          return ret;
        }
        break;
      }

      if ('"' == *c) {
        backslash_count = backslash_count * 2 + 1;
      }

      ret = append_backslashes(char_array, backslash_count);
      if (RCUTILS_RET_OK != ret) {
        return ret;
      }

      ret = rcutils_char_array_strncat(char_array, c, 1);
      if (RCUTILS_RET_OK != ret) {
        return ret;
      }
    }

    // Append closing quote
    ret = rcutils_char_array_strncat(char_array, "\"", 1);
    if (RCUTILS_RET_OK != ret) {
      return ret;
    }
  }

  return RCUTILS_RET_OK;
}

rcutils_process_t *
rcutils_start_process(
  const rcutils_string_array_t * args,
  rcutils_allocator_t * allocator)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(args, NULL);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(allocator, NULL);
  if (args->size < 1) {
    RCUTILS_SET_ERROR_MSG("args list is empty");
    return NULL;
  }
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    allocator, "allocator is invalid", return NULL);

  rcutils_process_t * process = allocator->zero_allocate(
    1, sizeof(rcutils_process_t), allocator->state);
  if (NULL == process) {
    return NULL;
  }
  process->allocator = *allocator;

#if defined _WIN32 || defined __CYGWIN__
  rcutils_char_array_t cmd = rcutils_get_zero_initialized_char_array();
  rcutils_ret_t ret = rcutils_char_array_init(&cmd, 0, allocator);
  if (RCUTILS_RET_OK != ret) {
    rcutils_process_close(process);
    return NULL;
  }

  ret = build_command_line(args, &cmd);
  if (RCUTILS_RET_OK != ret) {
    if (RCUTILS_RET_OK != rcutils_char_array_fini(&cmd)) {
      RCUTILS_SAFE_FWRITE_TO_STDERR("Failed to fini array.\n");
    }
    rcutils_process_close(process);
    return NULL;
  }

  STARTUPINFO start_info = {sizeof(start_info)};
  PROCESS_INFORMATION process_info = {0};
  if (!CreateProcess(
          NULL, cmd.buffer, NULL, NULL, TRUE, 0,
          NULL, NULL, &start_info, &process_info))
  {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING("Failed to create process: %lu", GetLastError());
    if (RCUTILS_RET_OK != rcutils_char_array_fini(&cmd)) {
      RCUTILS_SAFE_FWRITE_TO_STDERR("Failed to fini array.\n");
    }
    rcutils_process_close(process);
    return NULL;
  }

  if (RCUTILS_RET_OK != rcutils_char_array_fini(&cmd)) {
    RCUTILS_SAFE_FWRITE_TO_STDERR("Failed to fini array.\n");
  }

  CloseHandle(process_info.hThread);

  process->handle = process_info.hProcess;
  process->pid = process_info.dwProcessId;

  return process;
#else
  char **argv = allocator->zero_allocate(args->size + 1, sizeof(*argv), &allocator->state);
  if (NULL == argv) {
    return NULL;
  }
  memcpy(argv, args->data, args->size * sizeof(*argv));

  process->pid = fork();
  if (-1 == process->pid) {
    int error = errno;
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "Failed to fork process: %d (%s)", error, strerror(error));
    allocator->deallocate(argv, &allocator->state);
    rcutils_process_close(process);
    return NULL;
  } else if (0 != process->pid) {
    allocator->deallocate(argv, &allocator->state);
    return process;
  }

  (void)execvp(argv[0], argv);

  int error = errno;
  RCUTILS_SAFE_FWRITE_TO_STDERR_WITH_FORMAT_STRING(
    "Failed to execute process: %d (%s)", error, strerror(error));
  allocator->deallocate(argv, &allocator->state);
  exit(127);
#endif
}

void
rcutils_process_close(rcutils_process_t * process)
{
  if (NULL == process) {
    return;
  }

  rcutils_allocator_t allocator = process->allocator;
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    &allocator, "allocator is invalid", return );

#if defined _WIN32 || defined __CYGWIN__
  CloseHandle(process->handle);
#endif

  allocator.deallocate(process, allocator.state);
}

rcutils_ret_t
rcutils_process_wait(const rcutils_process_t * process, int * exit_code)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(process, RCUTILS_RET_INVALID_ARGUMENT);

#if defined _WIN32 || defined __CYGWIN__
  DWORD status;

  if (WAIT_FAILED == WaitForSingleObject(process->handle, INFINITE)) {
    return RCUTILS_RET_ERROR;
  }

  if (NULL != exit_code) {
    if (!GetExitCodeProcess(process->handle, &status)) {
      return RCUTILS_RET_ERROR;
    }
    *exit_code = status;
  }
#else
  int status;

  int ret = waitpid(process->pid, &status, 0);
  if (-1 == ret) {
    int error = errno;
    RCUTILS_SAFE_FWRITE_TO_STDERR_WITH_FORMAT_STRING(
      "Failed to wait for process %d: %d (%s)", process->pid, error, strerror(error));
    return RCUTILS_RET_ERROR;
  }

  if (NULL != exit_code) {
    if (WIFSIGNALED(status)) {
      *exit_code = -WTERMSIG(status);
    } else if (WIFEXITED(status)) {
      *exit_code = WEXITSTATUS(status);
    } else if (WIFSTOPPED(status)) {
      *exit_code = -WSTOPSIG(status);
    } else {
      return RCUTILS_RET_ERROR;
    }
  }
#endif

  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_qsort(void * ptr, size_t count, size_t size, int (* comp)(const void *, const void *))
{
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    comp, "comp is null", return RCUTILS_RET_INVALID_ARGUMENT);

  if (1 >= count) {
    return RCUTILS_RET_OK;
  }

  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    ptr, "ptr is null", return RCUTILS_RET_INVALID_ARGUMENT);

  qsort(ptr, count, size, comp);

  return RCUTILS_RET_OK;
}

char *
rcutils_repl_str(
  const char * str,
  const char * from,
  const char * to,
  const rcutils_allocator_t * allocator)
{
  RCUTILS_CHECK_ALLOCATOR(allocator, return NULL);
  /* Adjust each of the below values to suit your needs. */

  /* Increment positions cache size initially by this number. */
  size_t cache_sz_inc = 16;
  /* Thereafter, each time capacity needs to be increased,
   * multiply the increment by this factor. */
  const size_t cache_sz_inc_factor = 3;
  /* But never increment capacity by more than this number. */
  const size_t cache_sz_inc_max = 1048576;

  char *pret, *ret = NULL;
  const char *pstr2, *pstr = str;
  size_t i, count = 0;
  #if (__STDC_VERSION__ >= 199901L)
  uintptr_t *pos_cache_tmp, *pos_cache = NULL;
  #else
  ptrdiff_t *pos_cache_tmp, *pos_cache = NULL;
  #endif
  size_t cache_sz = 0;
  size_t cpylen, orglen, retlen, tolen, fromlen = strlen(from);

  /* Find all matches and cache their positions. */
  while ((pstr2 = strstr(pstr, from)) != NULL) {
    count++;

    /* Increase the cache size when necessary. */
    if (cache_sz < count) {
      cache_sz += cache_sz_inc;
      pos_cache_tmp =
        allocator->reallocate(pos_cache, sizeof(*pos_cache) * cache_sz, allocator->state);
      if (pos_cache_tmp == NULL) {
        goto end_repl_str;
      } else {
        pos_cache = pos_cache_tmp;
      }
      cache_sz_inc *= cache_sz_inc_factor;
      if (cache_sz_inc > cache_sz_inc_max) {
        cache_sz_inc = cache_sz_inc_max;
      }
    }

    pos_cache[count-1] = (size_t)(pstr2 - str);
    pstr = pstr2 + fromlen;
  }

  orglen = (size_t)(pstr - str) + strlen(pstr);

  /* Allocate memory for the post-replacement string. */
  if (count > 0) {
    tolen = strlen(to);
    retlen = orglen + (tolen - fromlen) * count;
  } else {
    retlen = orglen;
  }
  ret = allocator->allocate(retlen + 1, allocator->state);
  if (ret == NULL) {
    goto end_repl_str;
  }

  if (count == 0) {
    /* If no matches, then just duplicate the string. */
#if defined(_MSC_VER)
# pragma warning(push)
# pragma warning(disable: 4996)  // strcpy may be unsafe
#endif
    strcpy(ret, str);  // NOLINT
#if defined(_MSC_VER)
# pragma warning(pop)
#endif
  } else {
    /* Otherwise, duplicate the string whilst performing
     * the replacements using the position cache. */
    pret = ret;
    memcpy(pret, str, pos_cache[0]);
    pret += pos_cache[0];
    for (i = 0; i < count; i++) {
      memcpy(pret, to, tolen);
      pret += tolen;
      pstr = str + pos_cache[i] + fromlen;
      cpylen = (i == count-1 ? orglen : pos_cache[i+1]) - pos_cache[i] - fromlen;
      memcpy(pret, pstr, cpylen);
      pret += cpylen;
    }
    ret[retlen] = '\0';
  }

end_repl_str:
  /* Free the cache and return the post-replacement string,
   * which will be NULL in the event of an error. */
  allocator->deallocate(pos_cache, allocator->state);
  return ret;
}

static inline size_t min(size_t a, size_t b)
{
  return a < b ? a : b;
}

static inline uint32_t rotright(uint32_t a, const uint8_t b)
{
  assert(b < 32);
  return (a >> b) | (a << (32 - b));
}

static inline uint32_t ch(uint32_t x, uint32_t y, uint32_t z)
{
  return (x & y) ^ (~x & z);
}

static inline uint32_t maj(uint32_t x, uint32_t y, uint32_t z)
{
  return (x & y) ^ (x & z) ^ (y & z);
}

static inline uint32_t ep0(uint32_t x)
{
  return rotright(x, 2) ^ rotright(x, 13) ^ rotright(x, 22);
}

static inline uint32_t ep1(uint32_t x)
{
  return rotright(x, 6) ^ rotright(x, 11) ^ rotright(x, 25);
}

static inline uint32_t sig0(uint32_t x)
{
  return rotright(x, 7) ^ rotright(x, 18) ^ (x >> 3);
}

static inline uint32_t sig1(uint32_t x)
{
  return rotright(x, 17) ^ rotright(x, 19) ^ (x >> 10);
}

static void sha256_transform(rcutils_sha256_ctx_t * ctx)
{
  uint32_t a, b, c, d, e, f, g, h, i, j, t1, t2, m[64];
  uint8_t * data = ctx->data;

  for (i = 0, j = 0; i < 16; ++i, j += 4) {
    m[i] = (data[j] << 24) | (data[j + 1] << 16) | (data[j + 2] << 8) | (data[j + 3]);
  }
  for ( ; i < 64; ++i) {
    m[i] = sig1(m[i - 2]) + m[i - 7] + sig0(m[i - 15]) + m[i - 16];
  }

  a = ctx->state[0];
  b = ctx->state[1];
  c = ctx->state[2];
  d = ctx->state[3];
  e = ctx->state[4];
  f = ctx->state[5];
  g = ctx->state[6];
  h = ctx->state[7];

  for (i = 0; i < 64; ++i) {
    t1 = h + ep1(e) + ch(e, f, g) + k[i] + m[i];
    t2 = ep0(a) + maj(a, b, c);
    h = g;
    g = f;
    f = e;
    e = d + t1;
    d = c;
    c = b;
    b = a;
    a = t1 + t2;
  }

  ctx->state[0] += a;
  ctx->state[1] += b;
  ctx->state[2] += c;
  ctx->state[3] += d;
  ctx->state[4] += e;
  ctx->state[5] += f;
  ctx->state[6] += g;
  ctx->state[7] += h;
}

void rcutils_sha256_init(rcutils_sha256_ctx_t * ctx)
{
  ctx->datalen = 0;
  ctx->bitlen = 0;
  ctx->state[0] = 0x6a09e667;
  ctx->state[1] = 0xbb67ae85;
  ctx->state[2] = 0x3c6ef372;
  ctx->state[3] = 0xa54ff53a;
  ctx->state[4] = 0x510e527f;
  ctx->state[5] = 0x9b05688c;
  ctx->state[6] = 0x1f83d9ab;
  ctx->state[7] = 0x5be0cd19;
}

void rcutils_sha256_update(rcutils_sha256_ctx_t * ctx, const uint8_t * data, size_t len)
{
  size_t i, data_remaining, block_remaining, copy_len;
  i = 0;

  while (i < len) {
    data_remaining = len - i;
    block_remaining = 64 - ctx->datalen;
    copy_len = min(min(block_remaining, data_remaining), 64);

    memcpy(ctx->data + ctx->datalen, data + i, copy_len);
    ctx->datalen += copy_len;
    i += copy_len;

    if (ctx->datalen >= 64) {
      sha256_transform(ctx);
      ctx->bitlen += 512;
      ctx->datalen = 0;
    }
  }
}

void rcutils_sha256_final(
  rcutils_sha256_ctx_t * ctx, uint8_t output_hash[RCUTILS_SHA256_BLOCK_SIZE])
{
  size_t i = ctx->datalen;

  // Pad whatever data is left in the buffer.
  if (ctx->datalen < 56) {
    ctx->data[i++] = 0x80;
    memset(ctx->data + i, 0x00, 56 - i);
  } else {
    ctx->data[i++] = 0x80;
    if (i < 64) {
      memset(ctx->data + i, 0x00, 64 - i);
    }
    sha256_transform(ctx);
    memset(ctx->data, 0, 56);
  }

  // Append to the padding the total message's length in bits and transform.
  ctx->bitlen += ctx->datalen * 8;
  ctx->data[63] = (uint8_t)(ctx->bitlen >> 0);
  ctx->data[62] = (uint8_t)(ctx->bitlen >> 8);
  ctx->data[61] = (uint8_t)(ctx->bitlen >> 16);
  ctx->data[60] = (uint8_t)(ctx->bitlen >> 24);
  ctx->data[59] = (uint8_t)(ctx->bitlen >> 32);
  ctx->data[58] = (uint8_t)(ctx->bitlen >> 40);
  ctx->data[57] = (uint8_t)(ctx->bitlen >> 48);
  ctx->data[56] = (uint8_t)(ctx->bitlen >> 56);
  sha256_transform(ctx);

  // Since this implementation uses little endian byte ordering and SHA uses big endian,
  // reverse all the bytes when copying the final state to the output hash.
  for (i = 0; i < 4; ++i) {
    output_hash[i + 0] = (ctx->state[0] >> (24 - i * 8)) & 0x000000ff;
    output_hash[i + 4] = (ctx->state[1] >> (24 - i * 8)) & 0x000000ff;
    output_hash[i + 8] = (ctx->state[2] >> (24 - i * 8)) & 0x000000ff;
    output_hash[i + 12] = (ctx->state[3] >> (24 - i * 8)) & 0x000000ff;
    output_hash[i + 16] = (ctx->state[4] >> (24 - i * 8)) & 0x000000ff;
    output_hash[i + 20] = (ctx->state[5] >> (24 - i * 8)) & 0x000000ff;
    output_hash[i + 24] = (ctx->state[6] >> (24 - i * 8)) & 0x000000ff;
    output_hash[i + 28] = (ctx->state[7] >> (24 - i * 8)) & 0x000000ff;
  }
}

rcutils_shared_library_t
rcutils_get_zero_initialized_shared_library(void)
{
  static rcutils_shared_library_t zero_initialized_shared_library = {0};
  return zero_initialized_shared_library;
}

rcutils_ret_t
rcutils_load_shared_library(
  rcutils_shared_library_t * lib,
  const char * library_path,
  rcutils_allocator_t allocator)
{
  RCUTILS_CAN_RETURN_WITH_ERROR_OF(RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CAN_RETURN_WITH_ERROR_OF(RCUTILS_RET_BAD_ALLOC);
  RCUTILS_CAN_RETURN_WITH_ERROR_OF(RCUTILS_RET_ERROR);

  RCUTILS_CHECK_ARGUMENT_FOR_NULL(lib, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(library_path, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ALLOCATOR(&allocator, return RCUTILS_RET_INVALID_ARGUMENT);
  if (NULL != lib->lib_pointer) {
    RCUTILS_SET_ERROR_MSG("lib argument is not zero-initialized");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }

  rcutils_ret_t ret = RCUTILS_RET_OK;
  lib->allocator = allocator;

  // Delegate library path resolution to dynamic linker.

  // Since the given library path might be relative, let the dynamic
  // linker search for the binary object in all standard locations and
  // current process space (if already loaded) first.
  // Then lookup its full path with the handle obtained.
  // See POSIX dlopen() API and Windows' LoadLibrary() API documentation
  // for further reference.

#ifndef _WIN32
  lib->lib_pointer = dlopen(library_path, RTLD_LAZY);
  if (NULL == lib->lib_pointer) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING("dlopen error: %s", dlerror());
    return RCUTILS_RET_ERROR;
  }

#if defined(__APPLE__)
  const char * image_name = NULL;
  uint32_t image_count = _dyld_image_count();
  for (uint32_t i = 0; NULL == image_name && i < image_count; ++i) {
    // Iterate in reverse as the library is likely near the end of the list.
    const char * candidate_name = _dyld_get_image_name(image_count - i - 1);
    if (NULL == candidate_name) {
      RCUTILS_SET_ERROR_MSG("dyld image index out of range");
      ret = RCUTILS_RET_ERROR;
      goto fail;
    }
    void * handle = dlopen(candidate_name, RTLD_LAZY | RTLD_NOLOAD);
    if (handle == lib->lib_pointer) {
      image_name = candidate_name;
    }
    if (dlclose(handle) != 0) {
      RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING("dlclose error: %s", dlerror());
      ret = RCUTILS_RET_ERROR;
      goto fail;
    }
  }
  if (NULL == image_name) {
    RCUTILS_SET_ERROR_MSG("dyld image name could not be found");
    ret = RCUTILS_RET_ERROR;
    goto fail;
  }
  lib->library_path = rcutils_strdup(image_name, lib->allocator);
#elif defined(_GNU_SOURCE) && !defined(__QNXNTO__) && !defined(__ANDROID__) && !defined(__OHOS__)
  struct link_map * map = NULL;
  if (dlinfo(lib->lib_pointer, RTLD_DI_LINKMAP, &map) != 0) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING("dlinfo error: %s", dlerror());
    ret = RCUTILS_RET_ERROR;
    goto fail;
  }
  lib->library_path = rcutils_strdup(map->l_name, lib->allocator);
#else
  lib->library_path = rcutils_strdup(library_path, lib->allocator);
#endif
  if (NULL == lib->library_path) {
    RCUTILS_SET_ERROR_MSG("unable to allocate memory");
    ret = RCUTILS_RET_BAD_ALLOC;
    goto fail;
  }

  return RCUTILS_RET_OK;
fail:
  if (dlclose(lib->lib_pointer) != 0) {
    RCUTILS_SAFE_FWRITE_TO_STDERR_WITH_FORMAT_STRING(
      "dlclose error: %s\n", dlerror());
  }
  lib->lib_pointer = NULL;
  return ret;
#else
  HMODULE module = LoadLibrary(library_path);
  if (!module) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "LoadLibrary error: %lu", GetLastError());
    return RCUTILS_RET_ERROR;
  }

  for (DWORD buffer_capacity = MAX_PATH; ; buffer_capacity *= 2) {
    LPSTR buffer = lib->allocator.allocate(buffer_capacity, lib->allocator.state);
    if (NULL == buffer) {
      RCUTILS_SET_ERROR_MSG("unable to allocate memory");
      ret = RCUTILS_RET_BAD_ALLOC;
      goto fail;
    }
    DWORD buffer_size = GetModuleFileName(module, buffer, buffer_capacity);
    if (0 == buffer_size) {
      RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
        "GetModuleFileName error: %lu", GetLastError());
      ret = RCUTILS_RET_ERROR;
      goto fail;
    }
    if (GetLastError() == ERROR_INSUFFICIENT_BUFFER) {
      lib->allocator.deallocate(buffer, lib->allocator.state);
      continue;
    }
    lib->library_path = lib->allocator.reallocate(
      buffer, buffer_size + 1, lib->allocator.state);
    if (NULL == lib->library_path) {
      lib->library_path = buffer;
    }
    break;
  }
  lib->lib_pointer = (void *)module;

  return RCUTILS_RET_OK;
fail:
  if (!FreeLibrary(module)) {
    RCUTILS_SAFE_FWRITE_TO_STDERR_WITH_FORMAT_STRING(
      "FreeLibrary error: %lu\n", GetLastError());
  }
  return ret;
#endif  // _WIN32
}

void *
rcutils_get_symbol(const rcutils_shared_library_t * lib, const char * symbol_name)
{
  if (!lib || !lib->lib_pointer || (symbol_name == NULL)) {
    RCUTILS_SET_ERROR_MSG("invalid inputs arguments");
    return NULL;
  }

#ifndef _WIN32
  void * lib_symbol = dlsym(lib->lib_pointer, symbol_name);
  char * error = dlerror();
  if (error != NULL) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "Error getting the symbol '%s'. Error '%s'",
      symbol_name, error);
    return NULL;
  }
#else
  void * lib_symbol = GetProcAddress((HINSTANCE)(lib->lib_pointer), symbol_name);
  if (lib_symbol == NULL) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "Error getting the symbol '%s'. Error '%d'",
      symbol_name, GetLastError());
    return NULL;
  }
#endif  // _WIN32
  if (!lib_symbol) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "symbol '%s' does not exist in the library '%s'",
      symbol_name, lib->library_path);
    return NULL;
  }
  return lib_symbol;
}

bool
rcutils_has_symbol(const rcutils_shared_library_t * lib, const char * symbol_name)
{
  if (!lib || !lib->lib_pointer || symbol_name == NULL) {
    return false;
  }

#ifndef _WIN32
  // the correct way to test for an error is to call dlerror() to clear any old error conditions,
  // then call dlsym(), and then call dlerror() again, saving its return value into a variable,
  // and check whether this saved value is not NULL.
  dlerror(); /* Clear any existing error */
  void * lib_symbol = dlsym(lib->lib_pointer, symbol_name);
  return dlerror() == NULL && lib_symbol != 0;
#else
  void * lib_symbol = GetProcAddress((HINSTANCE)(lib->lib_pointer), symbol_name);
  return lib_symbol != NULL;
#endif  // _WIN32
}

rcutils_ret_t
rcutils_get_platform_library_name(
  const char * library_name,
  char * library_name_platform,
  unsigned int buffer_size,
  bool debug)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(library_name, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(library_name_platform, RCUTILS_RET_INVALID_ARGUMENT);

  int written = 0;

#if defined(__linux__) || defined(__QNXNTO__)
  if (debug) {
    if (buffer_size >= (strlen(library_name) + 8)) {
      written = rcutils_snprintf(
        library_name_platform, strlen(library_name) + 8, "lib%sd.so", library_name);
    }
  } else {
    if (buffer_size >= (strlen(library_name) + 7)) {
      written = rcutils_snprintf(
        library_name_platform, strlen(library_name) + 7, "lib%s.so", library_name);
    }
  }
#elif __APPLE__
  if (debug) {
    if (buffer_size >= (strlen(library_name) + 11)) {
      written = rcutils_snprintf(
        library_name_platform, strlen(library_name) + 11, "lib%sd.dylib", library_name);
    }
  } else {
    if (buffer_size >= (strlen(library_name) + 10)) {
      written = rcutils_snprintf(
        library_name_platform, strlen(library_name) + 10, "lib%s.dylib", library_name);
    }
  }
#elif _WIN32
#ifdef __MINGW64__
  if (debug) {
    if (buffer_size >= (strlen(library_name) + 9)) {
      written = rcutils_snprintf(
        library_name_platform, strlen(library_name) + 9, "lib%sd.dll", library_name);
    }
  } else {
    if (buffer_size >= (strlen(library_name) + 8)) {
      written = rcutils_snprintf(
        library_name_platform, strlen(library_name) + 8, "lib%s.dll", library_name);
    }
  }
#else
  if (debug) {
    if (buffer_size >= (strlen(library_name) + 6)) {
      written = rcutils_snprintf(
        library_name_platform, strlen(library_name) + 6, "%sd.dll", library_name);
    }
  } else {
    if (buffer_size >= (strlen(library_name) + 5)) {
      written = rcutils_snprintf(
        library_name_platform, strlen(library_name) + 5, "%s.dll", library_name);
    }
  }
#endif  // __MINGW64__
#endif
  if (written <= 0) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING(
      "failed to format library name: '%s'\n",
      library_name);
    return RCUTILS_RET_ERROR;
  }
  return RCUTILS_RET_OK;
}

bool
rcutils_is_shared_library_loaded(rcutils_shared_library_t * lib)
{
  return lib->lib_pointer != NULL;
}

int
rcutils_snprintf(char * buffer, size_t buffer_size, const char * format, ...)
{
  va_list args;
  va_start(args, format);
  int ret = rcutils_vsnprintf(buffer, buffer_size, format, args);
  va_end(args);
  return ret;
}

int
rcutils_vsnprintf(char * buffer, size_t buffer_size, const char * format, va_list args)
{
  RCUTILS_CAN_FAIL_WITH({errno = EINVAL; return -1;});

  if (NULL == format) {
    errno = EINVAL;
    return -1;
  }
  if (NULL == buffer && 0 == buffer_size) {
#ifndef _WIN32
    return vsnprintf(NULL, 0, format, args);
#else
    return _vscprintf(format, args);
#endif
  }
  if (NULL == buffer || 0 == buffer_size) {
    errno = EINVAL;
    return -1;
  }
  int ret;
#ifndef _WIN32
  ret = vsnprintf(buffer, buffer_size, format, args);
#else
  // errno isn't explicitly set to 0 when truncation occurs.
  errno = 0;
  ret = _vsnprintf_s(buffer, buffer_size, _TRUNCATE, format, args);
  if (-1 == ret && 0 == errno) {
    // This is the case where truncation has occurred, return how long it would have been.
    return _vscprintf(format, args);
  }
#endif
  return ret;
}

rcutils_ret_t
rcutils_split(
  const char * str,
  char delimiter,
  rcutils_allocator_t allocator,
  rcutils_string_array_t * string_array)
{
  if (NULL == string_array) {
    RCUTILS_SET_ERROR_MSG("string_array is null");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }
  if (NULL == str || '\0' == *str) {
    *string_array = rcutils_get_zero_initialized_string_array();
    return RCUTILS_RET_OK;
  }

  size_t string_size = strlen(str);

  // does it start with a delimiter?
  size_t lhs_offset = 0;
  if (str[0] == delimiter) {
    lhs_offset = 1;
  }

  // does it end with a delimiter?
  size_t rhs_offset = 0;
  if (str[string_size - 1] == delimiter) {
    rhs_offset = 1;
  }

  size_t array_size = 1;
  for (size_t i = lhs_offset; i < string_size - rhs_offset; ++i) {
    if (str[i] == delimiter) {
      ++array_size;
    }
  }
  rcutils_ret_t ret = rcutils_string_array_init(string_array, array_size, &allocator);
  if (ret != RCUTILS_RET_OK) {
    // rcutils_string_array_init already set the error
    return ret;
  }

  size_t token_counter = 0;
  size_t lhs = 0 + lhs_offset;
  size_t rhs = 0 + lhs_offset;
  for (; rhs < string_size - rhs_offset; ++rhs) {
    if (str[rhs] == delimiter) {
      // in case we have two consecutive delimiters
      // we ignore these and diminish the size of the array
      if (rhs - lhs < 1) {
        --string_array->size;
        string_array->data[string_array->size] = NULL;
      } else {
        // +2 (1+1) because lhs is index, not actual position
        // and nullterminating
        string_array->data[token_counter] =
          allocator.allocate((rhs - lhs + 2) * sizeof(char), allocator.state);
        if (NULL == string_array->data[token_counter]) {
          string_array->size = token_counter;
          goto fail;
        }
        snprintf(string_array->data[token_counter], (rhs - lhs + 1), "%s", str + lhs);
        ++token_counter;
      }
      lhs = rhs;
      ++lhs;
    }
  }

  // take care of trailing token
  if (rhs - lhs < 1) {
    --string_array->size;
    string_array->data[string_array->size] = NULL;
  } else {
    string_array->data[token_counter] =
      allocator.allocate((rhs - lhs + 2) * sizeof(char), allocator.state);
    if (NULL == string_array->data[token_counter]) {
      goto fail;
    }
    snprintf(string_array->data[token_counter], (rhs - lhs + 1), "%s", str + lhs);
  }

  return RCUTILS_RET_OK;

fail:
  if (rcutils_string_array_fini(string_array) != RCUTILS_RET_OK) {
    RCUTILS_SAFE_FWRITE_TO_STDERR("failed to finalize string array during error handling: ");
    RCUTILS_SAFE_FWRITE_TO_STDERR(rcutils_get_error_string().str);
    RCUTILS_SAFE_FWRITE_TO_STDERR("\n");
    rcutils_reset_error();
  }

  RCUTILS_SET_ERROR_MSG("unable to allocate memory for string array data");
  return RCUTILS_RET_BAD_ALLOC;
}

rcutils_ret_t
rcutils_split_last(
  const char * str,
  char delimiter,
  rcutils_allocator_t allocator,
  rcutils_string_array_t * string_array)
{
  if (NULL == str || strlen(str) == 0) {
    *string_array = rcutils_get_zero_initialized_string_array();
    return RCUTILS_RET_OK;
  }

  size_t string_size = strlen(str);

  // does it start with a delimiter?
  size_t lhs_offset = 0;
  if (str[0] == delimiter) {
    lhs_offset = 1;
  }

  // does it end with a delimiter?
  size_t rhs_offset = 0;
  if (str[string_size - 1] == delimiter) {
    rhs_offset = 1;
  }

  size_t found_last = string_size;
  for (size_t i = lhs_offset; i < string_size - rhs_offset; ++i) {
    if (str[i] == delimiter) {
      found_last = i;
    }
  }

  rcutils_ret_t result_error;
  if (found_last == string_size) {
    rcutils_ret_t ret = rcutils_string_array_init(string_array, 1, &allocator);
    if (ret != RCUTILS_RET_OK) {
      result_error = ret;
      goto fail;
    }
    string_array->data[0] =
      allocator.allocate((found_last - lhs_offset + 2) * sizeof(char), allocator.state);
    if (NULL == string_array->data[0]) {
      result_error = RCUTILS_RET_BAD_ALLOC;
      goto fail;
    }
    snprintf(string_array->data[0], found_last - lhs_offset + 1, "%s", str + lhs_offset);
  } else {
    rcutils_ret_t ret = rcutils_string_array_init(string_array, 2, &allocator);
    if (ret != RCUTILS_RET_OK) {
      result_error = ret;
      goto fail;
    }

    /*
     * The extra +1 after 'found_last' is to compensate its position
     * found_last is the index of the the last position the delimiter was found
     * and not the actual position in terms of counting from 1
     */
    size_t inner_rhs_offset = (str[found_last - 1] == delimiter) ? 1 : 0;
    string_array->data[0] = allocator.allocate(
      (found_last + 1 - lhs_offset - inner_rhs_offset + 1) * sizeof(char),
      allocator.state);
    if (NULL == string_array->data[0]) {
      result_error = RCUTILS_RET_BAD_ALLOC;
      goto fail;
    }
    snprintf(
      string_array->data[0], found_last + 1 - lhs_offset - inner_rhs_offset,
      "%s", str + lhs_offset);

    string_array->data[1] = allocator.allocate(
      (string_size - found_last - rhs_offset + 1) * sizeof(char),
      allocator.state);
    if (NULL == string_array->data[1]) {
      result_error = RCUTILS_RET_BAD_ALLOC;
      goto fail;
    }
    snprintf(
      string_array->data[1], string_size - found_last - rhs_offset, "%s",
      str + found_last + 1);
  }

  return RCUTILS_RET_OK;

fail:
  if (rcutils_string_array_fini(string_array) != RCUTILS_RET_OK) {
    RCUTILS_LOG_ERROR(
      "failed to clean up on error (leaking memory): '%s'", rcutils_get_error_string().str);
  }
  return result_error;
}

int
rcutils_strcasecmp(
  const char * s1,
  const char * s2,
  int * value)
{
  if (s1 == NULL || s2 == NULL || value == NULL) {
    return -1;
  }
#ifndef _WIN32
  *value = strcasecmp(s1, s2);
#else
  *value = _stricmp(s1, s2);
#endif
  return 0;
}

int
rcutils_strncasecmp(
  const char * s1,
  const char * s2,
  size_t n,
  int * value)
{
  if (s1 == NULL || s2 == NULL || value == NULL) {
    return -1;
  }
#ifndef _WIN32
  *value = strncasecmp(s1, s2, n);
#else
  *value = _strnicmp(s1, s2, n);
#endif
  return 0;
}

char *
rcutils_strdup(const char * str, rcutils_allocator_t allocator)
{
  RCUTILS_CAN_RETURN_WITH_ERROR_OF(NULL);

  return rcutils_strndup(str, SIZE_MAX, allocator);
}

char *
rcutils_strndup(const char * str, size_t max_length, rcutils_allocator_t allocator)
{
  RCUTILS_CAN_RETURN_WITH_ERROR_OF(NULL);

  if (NULL == str) {
    return NULL;
  }
  RCUTILS_CHECK_ALLOCATOR(&allocator, return NULL);
  const char * p = memchr(str, '\0', max_length);
  size_t string_length = p == NULL ? max_length : (size_t)(p - str);
  char * new_string = allocator.allocate(string_length + 1, allocator.state);
  if (NULL == new_string) {
    return NULL;
  }
  memcpy(new_string, str, string_length);
  new_string[string_length] = '\0';
  return new_string;
}

void
rcutils_strerror(char * buffer, size_t buffer_length)
{
#if defined(_WIN32)
  strerror_s(buffer, buffer_length, errno);
#elif defined(_GNU_SOURCE) && (!defined(ANDROID) || __ANDROID_API__ >= 23) && !defined(__QNXNTO__)
  /* GNU-specific */
  char * msg = strerror_r(errno, buffer, buffer_length);
  if (msg != buffer) {
    strncpy(buffer, msg, buffer_length);
    buffer[buffer_length - 1] = '\0';
  }
#else
  /* XSI-compliant */
  int error_status = strerror_r(errno, buffer, buffer_length);
  if (error_status != 0) {
    strncpy(buffer, "Failed to get error", buffer_length);
    buffer[buffer_length - 1] = '\0';
  }
#endif
}

rcutils_string_array_t
rcutils_get_zero_initialized_string_array(void)
{
  static rcutils_string_array_t array = {0};
  return array;
}

rcutils_ret_t
rcutils_string_array_init(
  rcutils_string_array_t * string_array,
  size_t size,
  const rcutils_allocator_t * allocator)
{
  RCUTILS_CAN_RETURN_WITH_ERROR_OF(RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CAN_RETURN_WITH_ERROR_OF(RCUTILS_RET_BAD_ALLOC);

  if (NULL == allocator) {
    RCUTILS_SET_ERROR_MSG("allocator is null");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }
  if (NULL == string_array) {
    RCUTILS_SET_ERROR_MSG("string_array is null");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }
  string_array->size = size;
  string_array->data = allocator->zero_allocate(size, sizeof(char *), allocator->state);
  if (NULL == string_array->data && 0 != size) {
    RCUTILS_SET_ERROR_MSG("failed to allocate string array");
    return RCUTILS_RET_BAD_ALLOC;
  }
  string_array->allocator = *allocator;
  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_string_array_fini(rcutils_string_array_t * string_array)
{
  RCUTILS_CAN_RETURN_WITH_ERROR_OF(RCUTILS_RET_INVALID_ARGUMENT);

  if (NULL == string_array) {
    RCUTILS_SET_ERROR_MSG("string_array is null");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }

  if (NULL == string_array->data) {
    return RCUTILS_RET_OK;
  }

  rcutils_allocator_t * allocator = &string_array->allocator;
  if (!rcutils_allocator_is_valid(allocator)) {
    RCUTILS_SET_ERROR_MSG("allocator is invalid");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }
  size_t i;
  for (i = 0; i < string_array->size; ++i) {
    allocator->deallocate(string_array->data[i], allocator->state);
    string_array->data[i] = NULL;
  }
  allocator->deallocate(string_array->data, allocator->state);
  string_array->data = NULL;
  string_array->size = 0;

  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_string_array_cmp(
  const rcutils_string_array_t * lhs,
  const rcutils_string_array_t * rhs,
  int * res)
{
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    lhs, "lhs string array is null", return RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    rhs, "rhs string array is null", return RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    res, "res argument is null", return RCUTILS_RET_INVALID_ARGUMENT);

  size_t smallest_size = lhs->size;
  if (rhs->size < smallest_size) {
    smallest_size = rhs->size;
  }

  if (smallest_size > 0) {
    RCUTILS_CHECK_FOR_NULL_WITH_MSG(
      lhs->data, "lhs->data is null", return RCUTILS_RET_INVALID_ARGUMENT);
    RCUTILS_CHECK_FOR_NULL_WITH_MSG(
      rhs->data, "rhs->data is null", return RCUTILS_RET_INVALID_ARGUMENT);
  }

  for (size_t i = 0; i < smallest_size; ++i) {
    RCUTILS_CHECK_FOR_NULL_WITH_MSG(
      lhs->data[i], "lhs array element is null", return RCUTILS_RET_ERROR);
    RCUTILS_CHECK_FOR_NULL_WITH_MSG(
      rhs->data[i], "rhs array element is null", return RCUTILS_RET_ERROR);
    // Loop until we find a pair of strings that are not equal
    int strcmp_res = strcmp(lhs->data[i], rhs->data[i]);
    if (0 != strcmp_res) {
      *res = strcmp_res;
      return RCUTILS_RET_OK;
    }
  }

  // If all strings equal, compare array sizes
  *res = 0;
  if (lhs->size < rhs->size) {
    *res = -1;
  } else if (lhs->size > rhs->size) {
    *res = 1;
  }
  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_string_array_resize(
  rcutils_string_array_t * string_array,
  size_t new_size)
{
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    string_array, "string_array is null", return RCUTILS_RET_INVALID_ARGUMENT);

  if (string_array->size == new_size) {
    return RCUTILS_RET_OK;
  }

  rcutils_allocator_t * allocator = &string_array->allocator;
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    allocator, "allocator is invalid", return RCUTILS_RET_INVALID_ARGUMENT);

  // Stash entries being removed
  rcutils_string_array_t to_reclaim = rcutils_get_zero_initialized_string_array();
  if (new_size < string_array->size) {
    size_t num_removed = string_array->size - new_size;
    rcutils_ret_t ret = rcutils_string_array_init(&to_reclaim, num_removed, allocator);
    if (RCUTILS_RET_OK != ret) {
      // rcutils_string_array_init should have already set an error message
      return ret;
    }
    memcpy(
      to_reclaim.data, &string_array->data[new_size],
      to_reclaim.size * sizeof(char *));
  }

  char ** new_data = allocator->reallocate(
    string_array->data, new_size * sizeof(char *), allocator->state);
  if (NULL == new_data && 0 != new_size) {
    RCUTILS_SET_ERROR_MSG("failed to allocate string array");
    for (size_t i = 0; i < to_reclaim.size; ++i) {
      to_reclaim.data[i] = NULL;
    }
    rcutils_ret_t ret = rcutils_string_array_fini(&to_reclaim);
    if (RCUTILS_RET_OK != ret) {
      RCUTILS_SET_ERROR_MSG("memory was leaked during error handling");
    }
    return RCUTILS_RET_BAD_ALLOC;
  }
  string_array->data = new_data;

  // Zero-initialize new entries
  for (size_t i = string_array->size; i < new_size; ++i) {
    string_array->data[i] = NULL;
  }

  string_array->size = new_size;

  // Lastly, reclaim removed entries
  return rcutils_string_array_fini(&to_reclaim);
}

int
rcutils_string_array_sort_compare(const void * lhs, const void * rhs)
{
  const char * left = *(const char **)lhs;
  const char * right = *(const char **)rhs;
  if (NULL == left) {
    return NULL == right ? 0 : 1;
  } else if (NULL == right) {
    return -1;
  }
  return strcmp(left, right);
}

rcutils_string_map_t
rcutils_get_zero_initialized_string_map(void)
{
  static rcutils_string_map_t zero_initialized_string_map = {0};
  return zero_initialized_string_map;
}

rcutils_ret_t
rcutils_string_map_init(
  rcutils_string_map_t * string_map,
  size_t initial_capacity,
  rcutils_allocator_t allocator)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(string_map, RCUTILS_RET_INVALID_ARGUMENT);
  if (string_map->impl != NULL) {
    RCUTILS_SET_ERROR_MSG("string_map already initialized");
    return RCUTILS_RET_STRING_MAP_ALREADY_INIT;
  }
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    &allocator, "invalid allocator", return RCUTILS_RET_INVALID_ARGUMENT)
  string_map->impl = allocator.allocate(sizeof(rcutils_string_map_impl_t), allocator.state);
  if (NULL == string_map->impl) {
    RCUTILS_SET_ERROR_MSG("failed to allocate memory for string map impl struct");
    return RCUTILS_RET_BAD_ALLOC;
  }
  string_map->impl->key_value_pairs = NULL;
  string_map->impl->capacity = 0;
  string_map->impl->size = 0;
  string_map->impl->allocator = allocator;
  rcutils_ret_t ret = rcutils_string_map_reserve(string_map, initial_capacity);
  if (ret != RCUTILS_RET_OK) {
    // error mesage is already set, clean up and return the ret
    allocator.deallocate(string_map->impl, allocator.state);
    string_map->impl = NULL;
    return ret;
  }
  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_string_map_fini(rcutils_string_map_t * string_map)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(string_map, RCUTILS_RET_INVALID_ARGUMENT);
  if (NULL == string_map->impl) {
    return RCUTILS_RET_OK;
  }
  rcutils_ret_t ret = rcutils_string_map_clear(string_map);
  if (ret != RCUTILS_RET_OK) {
    // error message already set
    return ret;
  }
  ret = rcutils_string_map_reserve(string_map, 0);
  if (ret != RCUTILS_RET_OK) {
    // error message already set
    return ret;
  }
  rcutils_allocator_t allocator = string_map->impl->allocator;
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    &allocator, "allocator is invalid", return RCUTILS_RET_INVALID_ARGUMENT);

  allocator.deallocate(string_map->impl, allocator.state);
  string_map->impl = NULL;

  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_string_map_get_capacity(const rcutils_string_map_t * string_map, size_t * capacity)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(string_map, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    string_map->impl, "invalid string map", return RCUTILS_RET_STRING_MAP_INVALID);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(capacity, RCUTILS_RET_INVALID_ARGUMENT);
  // *INDENT-OFF* (prevent uncrustify getting this wrong)
  *capacity = string_map->impl->capacity;
  // *INDENT-ON*
  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_string_map_get_size(const rcutils_string_map_t * string_map, size_t * size)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(string_map, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    string_map->impl, "invalid string map", return RCUTILS_RET_STRING_MAP_INVALID);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(size, RCUTILS_RET_INVALID_ARGUMENT);
  {  // otherwise uncrustify moves the * to the end of the previous line...
    *size = string_map->impl->size;
  }
  return RCUTILS_RET_OK;
}

static void
__remove_key_and_value_at_index(rcutils_string_map_impl_t * string_map_impl, size_t index)
{
  rcutils_allocator_t allocator = string_map_impl->allocator;
  allocator.deallocate(string_map_impl->key_value_pairs[index].key, allocator.state);
  string_map_impl->key_value_pairs[index].key = NULL;
  allocator.deallocate(string_map_impl->key_value_pairs[index].value, allocator.state);
  string_map_impl->key_value_pairs[index].value = NULL;
  string_map_impl->size--;
}

rcutils_ret_t
rcutils_string_map_reserve(rcutils_string_map_t * string_map, size_t capacity)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(string_map, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    string_map->impl, "invalid string map", return RCUTILS_RET_STRING_MAP_INVALID);
  rcutils_allocator_t allocator = string_map->impl->allocator;
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    &allocator, "allocator is invalid", return RCUTILS_RET_INVALID_ARGUMENT);
  // short circuit, if requested capacity is less than the size of the map
  if (capacity < string_map->impl->size) {
    // set the capacity to the current size instead
    return rcutils_string_map_reserve(string_map, string_map->impl->size);
  }
  if (capacity == string_map->impl->capacity) {
    // if requested capacity is equal to the current capacity, nothing to do
    return RCUTILS_RET_OK;
  } else if (capacity == 0) {
    // if the requested capacity is zero, then make sure the existing keys and values are free'd
    // size is known to be 0 here because of the recursive call above.
    allocator.deallocate(string_map->impl->key_value_pairs, allocator.state);
    string_map->impl->key_value_pairs = NULL;
    // falls through to normal function end
  } else {
    // if the capacity non-zero and different, use realloc to increase/shrink the size
    // note that realloc when the pointer is NULL is the same as malloc
    // note also that realloc will shrink the space if needed

    // ensure that reallocate won't overflow SIZE_MAX
    if (capacity > (SIZE_MAX / sizeof(key_value_pair_t))) {
      RCUTILS_SET_ERROR_MSG("requested capacity for string_map too large");
      return RCUTILS_RET_BAD_ALLOC;
    }

    // resize the keys and values, assigning the result only if it succeeds
    key_value_pair_t * new_key_value_pairs = allocator.reallocate(
      string_map->impl->key_value_pairs, capacity * sizeof(key_value_pair_t), allocator.state);
    if (NULL == new_key_value_pairs) {
      RCUTILS_SET_ERROR_MSG("failed to allocate memory for string_map key-value pairs");
      return RCUTILS_RET_BAD_ALLOC;
    }
    string_map->impl->key_value_pairs = new_key_value_pairs;

    // zero out the new memory, if there is any (expanded instead of shrunk)
    if (capacity > string_map->impl->capacity) {
      for (size_t i = string_map->impl->capacity; i < capacity; ++i) {
        string_map->impl->key_value_pairs[i].key = NULL;
        string_map->impl->key_value_pairs[i].value = NULL;
      }
    }
    // falls through to normal function end
  }
  string_map->impl->capacity = capacity;
  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_string_map_clear(rcutils_string_map_t * string_map)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(string_map, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    string_map->impl, "invalid string map", return RCUTILS_RET_STRING_MAP_INVALID);

  for (size_t i = 0; i < string_map->impl->capacity; ++i) {
    if (string_map->impl->key_value_pairs[i].key != NULL) {
      __remove_key_and_value_at_index(string_map->impl, i);
    }
  }

  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_string_map_set(rcutils_string_map_t * string_map, const char * key, const char * value)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(string_map, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    string_map->impl, "invalid string map", return RCUTILS_RET_STRING_MAP_INVALID);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(key, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(value, RCUTILS_RET_INVALID_ARGUMENT);
  rcutils_ret_t ret = rcutils_string_map_set_no_resize(string_map, key, value);
  // if it fails due to not enough space, resize and try again
  if (ret == RCUTILS_RET_NOT_ENOUGH_SPACE) {
    rcutils_reset_error();
    // default to doubling the size of the map's capacity
    size_t new_capacity = (string_map->impl->capacity) ? 2 * string_map->impl->capacity : 1;
    ret = rcutils_string_map_reserve(string_map, new_capacity);
    if (ret != RCUTILS_RET_OK) {
      // error message is already set
      return ret;
    }
    // try again
    return rcutils_string_map_set_no_resize(string_map, key, value);
  }
  return ret;
}

static bool
__get_index_of_key_if_exists(
  rcutils_string_map_impl_t * string_map_impl,
  const char * key,
  size_t key_length,
  size_t * index)
{
  size_t i = 0;
  for (; i < string_map_impl->capacity; ++i) {
    if (NULL == string_map_impl->key_value_pairs[i].key) {
      continue;
    }
    size_t cmp_count = strlen(string_map_impl->key_value_pairs[i].key);
    if (key_length > cmp_count) {
      cmp_count = key_length;
    }
    if (strncmp(key, string_map_impl->key_value_pairs[i].key, cmp_count) == 0) {
      *index = i;
      return true;
    }
  }
  return false;
}

rcutils_ret_t
rcutils_string_map_set_no_resize(
  rcutils_string_map_t * string_map,
  const char * key,
  const char * value)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(string_map, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    string_map->impl, "invalid string map", return RCUTILS_RET_STRING_MAP_INVALID);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(key, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(value, RCUTILS_RET_INVALID_ARGUMENT);
  rcutils_allocator_t allocator = string_map->impl->allocator;
  RCUTILS_CHECK_ALLOCATOR_WITH_MSG(
    &allocator, "allocator is invalid", return RCUTILS_RET_INVALID_ARGUMENT);
  size_t key_index;
  bool should_free_key_on_error = false;
  bool key_exists = __get_index_of_key_if_exists(string_map->impl, key, strlen(key), &key_index);
  if (!key_exists) {
    // create space for, and store the key if it doesn't exist yet
    assert(string_map->impl->size <= string_map->impl->capacity);  // defensive, should not happen
    if (string_map->impl->size == string_map->impl->capacity) {
      return RCUTILS_RET_NOT_ENOUGH_SPACE;
    }
    for (key_index = 0; key_index < string_map->impl->capacity; ++key_index) {
      if (NULL == string_map->impl->key_value_pairs[key_index].key) {
        break;
      }
    }
    assert(key_index < string_map->impl->capacity);  // defensive, this should not happen
    string_map->impl->key_value_pairs[key_index].key = rcutils_strdup(key, allocator);
    if (NULL == string_map->impl->key_value_pairs[key_index].key) {
      RCUTILS_SET_ERROR_MSG("failed to allocate memory for key");
      return RCUTILS_RET_BAD_ALLOC;
    }
    should_free_key_on_error = true;
  }
  // at this point the key is in the map, waiting for the value to set/overwritten
  char * original_value = string_map->impl->key_value_pairs[key_index].value;
  char * new_value = rcutils_strdup(value, allocator);
  if (NULL == new_value) {
    RCUTILS_SET_ERROR_MSG("failed to allocate memory for value");
    if (should_free_key_on_error) {
      allocator.deallocate(string_map->impl->key_value_pairs[key_index].key, allocator.state);
      string_map->impl->key_value_pairs[key_index].key = NULL;
    }
    return RCUTILS_RET_BAD_ALLOC;
  }
  string_map->impl->key_value_pairs[key_index].value = new_value;
  if (original_value != NULL) {
    // clean up the old value if not NULL
    allocator.deallocate(original_value, allocator.state);
  }
  if (!key_exists) {
    // if the key didn't exist, then we had to add it, so increase the size
    string_map->impl->size++;
  }
  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_string_map_unset(rcutils_string_map_t * string_map, const char * key)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(string_map, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    string_map->impl, "invalid string map", return RCUTILS_RET_STRING_MAP_INVALID);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(key, RCUTILS_RET_INVALID_ARGUMENT);
  size_t key_index;
  if (!__get_index_of_key_if_exists(string_map->impl, key, strlen(key), &key_index)) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING("key '%s' not found", key);
    return RCUTILS_RET_STRING_KEY_NOT_FOUND;
  }
  __remove_key_and_value_at_index(string_map->impl, key_index);
  return RCUTILS_RET_OK;
}

bool
rcutils_string_map_key_exists(const rcutils_string_map_t * string_map, const char * key)
{
  if (NULL == key) {
    return false;
  }
  return rcutils_string_map_key_existsn(string_map, key, strlen(key));
}

bool
rcutils_string_map_key_existsn(
  const rcutils_string_map_t * string_map,
  const char * key,
  size_t key_length)
{
  if (NULL == string_map || NULL == string_map->impl || NULL == key) {
    return false;
  }
  size_t key_index;
  bool key_exists = __get_index_of_key_if_exists(string_map->impl, key, key_length, &key_index);
  return key_exists;
}

const char *
rcutils_string_map_get(const rcutils_string_map_t * string_map, const char * key)
{
  if (NULL == key) {
    return NULL;
  }
  return rcutils_string_map_getn(string_map, key, strlen(key));
}

const char *
rcutils_string_map_getn(
  const rcutils_string_map_t * string_map,
  const char * key,
  size_t key_length)
{
  if (NULL == string_map || NULL == string_map->impl || NULL == key) {
    return NULL;
  }
  size_t key_index;
  if (__get_index_of_key_if_exists(string_map->impl, key, key_length, &key_index)) {
    return string_map->impl->key_value_pairs[key_index].value;
  }
  return NULL;
}

const char *
rcutils_string_map_get_next_key(
  const rcutils_string_map_t * string_map,
  const char * key)
{
  if (NULL == string_map || !string_map->impl) {
    return NULL;
  }
  if (string_map->impl->size == 0) {
    return NULL;
  }
  size_t start_index = 0;
  if (key != NULL) {
    // if given a key, try to find it
    bool given_key_found = false;
    size_t i = 0;
    for (; i < string_map->impl->capacity; ++i) {
      if (string_map->impl->key_value_pairs[i].key == key) {
        given_key_found = true;
        // given key found at index i, start there + 1
        start_index = i + 1;
      }
    }
    if (!given_key_found) {
      // given key not found, cannot return next key with that
      return NULL;
    }
  }
  // iterate through the storage and look for another non-NULL key to return
  size_t i = start_index;
  for (; i < string_map->impl->capacity; ++i) {
    if (string_map->impl->key_value_pairs[i].key != NULL) {
      // next key found, return it
      return string_map->impl->key_value_pairs[i].key;
    }
  }
  // next key (or first key) not found
  return NULL;
}

rcutils_ret_t
rcutils_string_map_copy(
  const rcutils_string_map_t * src_string_map,
  rcutils_string_map_t * dst_string_map)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(src_string_map, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(dst_string_map, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    src_string_map->impl, "source string map is invalid", return RCUTILS_RET_STRING_MAP_INVALID);
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    dst_string_map->impl, "destination string map is invalid",
    return RCUTILS_RET_STRING_MAP_INVALID);
  const char * key = rcutils_string_map_get_next_key(src_string_map, NULL);
  while (key != NULL) {
    const char * value = rcutils_string_map_get(src_string_map, key);
    if (NULL == value) {
      RCUTILS_SET_ERROR_MSG("unable to get value for known key, should not happen");
      return RCUTILS_RET_ERROR;
    }
    rcutils_ret_t ret = rcutils_string_map_set(dst_string_map, key, value);
    if (ret != RCUTILS_RET_OK) {
      // error message already set
      return ret;
    }
    key = rcutils_string_map_get_next_key(src_string_map, key);
  }
  return RCUTILS_RET_OK;
}

size_t
rcutils_strnlen(const char * s, size_t maxlen)
{
  const char * found = memchr(s, '\0', maxlen);
  return found ? (size_t)(found - s) : maxlen;
}

void rcutils_fault_injection_set_count(int_least64_t count)
{
  rcutils_atomic_store(&g_rcutils_fault_injection_count, count);
}

int_least64_t rcutils_fault_injection_get_count(void)
{
  int_least64_t count = 0;
  rcutils_atomic_load(&g_rcutils_fault_injection_count, count);
  return count;
}

bool rcutils_fault_injection_is_test_complete(void)
{
#ifndef RCUTILS_ENABLE_FAULT_INJECTION
  return true;
#else  // RCUTILS_ENABLE_FAULT_INJECTION
  return rcutils_fault_injection_get_count() > RCUTILS_FAULT_INJECTION_NEVER_FAIL;
#endif  // RCUTILS_ENABLE_FAULT_INJECTION
}

int_least64_t _rcutils_fault_injection_maybe_fail(void)
{
  bool set_atomic_success = false;
  int_least64_t current_count = rcutils_fault_injection_get_count();
  do {
    // A fault_injection_count less than 0 means that maybe_fail doesn't fail, so just return.
    if (current_count <= RCUTILS_FAULT_INJECTION_NEVER_FAIL) {
      return current_count;
    }

    // Otherwise decrement by one, but do so in a thread-safe manner so that exactly one calling
    // thread gets the 0 case.
    int_least64_t desired_count = current_count - 1;
    rcutils_atomic_compare_exchange_strong(
      &g_rcutils_fault_injection_count, set_atomic_success, &current_count, desired_count);
  } while (!set_atomic_success);
  return current_count;
}

rcutils_ret_t
rcutils_time_point_value_as_nanoseconds_string(
  const rcutils_time_point_value_t * time_point,
  char * str,
  size_t str_size)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(time_point, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(str, RCUTILS_RET_INVALID_ARGUMENT);
  if (0 == str_size) {
    return RCUTILS_RET_OK;
  }
  if (rcutils_snprintf(str, str_size, "%.19" PRId64, *time_point) < 0) {
    RCUTILS_SET_ERROR_MSG("failed to format time point into string as nanoseconds");
    return RCUTILS_RET_ERROR;
  }
  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_time_point_value_as_date_string(
  const rcutils_time_point_value_t * time_point,
  char * str,
  size_t str_size)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(time_point, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(str, RCUTILS_RET_INVALID_ARGUMENT);
  if (0 == str_size) {
    return RCUTILS_RET_OK;
  }
  // best to abs it to avoid issues with negative values in C89, see:
  //   https://stackoverflow.com/a/3604984/671658
  uint64_t abs_time_point = (uint64_t)llabs(*time_point);
  // break into two parts to avoid floating point error
  uint64_t seconds = abs_time_point / (1000u * 1000u * 1000u);
  uint64_t nanoseconds = abs_time_point % (1000u * 1000u * 1000u);
  // Make sure the buffer is large enough to hold the largest possible uint64_t
  char nanoseconds_str[21];

  if (rcutils_snprintf(nanoseconds_str, sizeof(nanoseconds_str), "%" PRIu64, nanoseconds) < 0) {
    RCUTILS_SET_ERROR_MSG("failed to format time point nanoseconds into string");
    return RCUTILS_RET_ERROR;
  }

  time_t now_t = (time_t)(seconds);
  struct tm ptm = {.tm_year = 0, .tm_mday = 0};
#ifdef _WIN32
  if (localtime_s(&ptm, &now_t) != 0) {
    RCUTILS_SET_ERROR_MSG("failed to get localtime");
    return RCUTILS_RET_ERROR;
  }
#else
  if (localtime_r(&now_t, &ptm) == NULL) {
    RCUTILS_SET_ERROR_MSG("failed to get localtime");
    return RCUTILS_RET_ERROR;
  }
#endif

  if (str_size < 32 || strftime(str, 32, "%Y-%m-%d %H:%M:%S", &ptm) == 0) {
    RCUTILS_SET_ERROR_MSG("failed to format time point into string as iso8601_date");
    return RCUTILS_RET_ERROR;
  }
  static const int date_end_position = 19;
  if (rcutils_snprintf(
      &str[date_end_position], str_size - date_end_position, ".%.3s",
      nanoseconds_str) < 0)
  {
    RCUTILS_SET_ERROR_MSG("failed to format time point into string as date_time_with_ms");
    return RCUTILS_RET_ERROR;
  }

  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_time_point_value_as_seconds_string(
  const rcutils_time_point_value_t * time_point,
  char * str,
  size_t str_size)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(time_point, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(str, RCUTILS_RET_INVALID_ARGUMENT);
  if (0 == str_size) {
    return RCUTILS_RET_OK;
  }
  // best to abs it to avoid issues with negative values in C89, see:
  //   https://stackoverflow.com/a/3604984/671658
  uint64_t abs_time_point = (uint64_t)llabs(*time_point);
  // break into two parts to avoid floating point error
  uint64_t seconds = abs_time_point / (1000u * 1000u * 1000u);
  uint64_t nanoseconds = abs_time_point % (1000u * 1000u * 1000u);
  if (
    rcutils_snprintf(
      str, str_size, "%s%.10" PRId64 ".%.9" PRId64,
      (*time_point >= 0) ? "" : "-", seconds, nanoseconds) < 0)
  {
    RCUTILS_SET_ERROR_MSG("failed to format time point into string as float seconds");
    return RCUTILS_RET_ERROR;
  }
  return RCUTILS_RET_OK;
}

static inline bool would_be_negative(const struct timespec * const now)
{
  return now->tv_sec < 0 || (now->tv_nsec < 0 && now->tv_sec == 0);
}

rcutils_ret_t
rcutils_system_time_now(rcutils_time_point_value_t * now)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(now, RCUTILS_RET_INVALID_ARGUMENT);
  struct timespec timespec_now;
  // Using clock_gettime(CLOCK_REALTIME) matches what both Linux and macOS use.
  // For macOS, see the clang implementation at
  // (https://github.com/llvm/llvm-project/blob/baebe12ad0d6f514cd33e418d6504075d3e79c0a/libcxx/src/chrono.cpp)
  if (clock_gettime(CLOCK_REALTIME, &timespec_now) < 0) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING("Failed to get system time: %d", errno);
    return RCUTILS_RET_ERROR;
  }
  if (would_be_negative(&timespec_now)) {
    RCUTILS_SET_ERROR_MSG("unexpected negative time");
    return RCUTILS_RET_ERROR;
  }
  *now = RCUTILS_S_TO_NS((int64_t)timespec_now.tv_sec) + timespec_now.tv_nsec;
  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_steady_time_now(rcutils_time_point_value_t * now)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(now, RCUTILS_RET_INVALID_ARGUMENT);
  struct timespec timespec_now;
  clockid_t monotonic_clock = CLOCK_MONOTONIC;

#if defined(__MACH__) && defined(__APPLE__)
  // On macOS, use CLOCK_MONOTONIC_RAW, which matches the clang implementation
  // (https://github.com/llvm/llvm-project/blob/baebe12ad0d6f514cd33e418d6504075d3e79c0a/libcxx/src/chrono.cpp)
  monotonic_clock = CLOCK_MONOTONIC_RAW;
#endif  // defined(__MACH__) && defined(__APPLE__)

  if (clock_gettime(monotonic_clock, &timespec_now) < 0) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING("Failed to get steady time: %d", errno);
    return RCUTILS_RET_ERROR;
  }
  if (would_be_negative(&timespec_now)) {
    RCUTILS_SET_ERROR_MSG("unexpected negative time");
    return RCUTILS_RET_ERROR;
  }
  *now = RCUTILS_S_TO_NS((int64_t)timespec_now.tv_sec) + timespec_now.tv_nsec;
  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_raw_steady_time_now(rcutils_time_point_value_t * now)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(now, RCUTILS_RET_INVALID_ARGUMENT);
  struct timespec timespec_now;

#if defined(CLOCK_MONOTONIC_RAW)
  clockid_t monotonic_raw_clock = CLOCK_MONOTONIC_RAW;
#else
  clockid_t monotonic_raw_clock = CLOCK_MONOTONIC;
  RCUTILS_LOG_WARN_ONCE(
    "CLOCK_MONOTONIC_RAW is not supported by the platform, using CLOCK_MONOTONIC "
    "instead. This may not provide the desired raw steady time behavior.");
#endif

  if (clock_gettime(monotonic_raw_clock, &timespec_now) < 0) {
    RCUTILS_SET_ERROR_MSG_WITH_FORMAT_STRING("Failed to get raw steady time: %d", errno);
    return RCUTILS_RET_ERROR;
  }
  if (would_be_negative(&timespec_now)) {
    RCUTILS_SET_ERROR_MSG("unexpected negative time");
    return RCUTILS_RET_ERROR;
  }
  *now = RCUTILS_S_TO_NS((int64_t)timespec_now.tv_sec) + timespec_now.tv_nsec;
  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_system_time_now(rcutils_time_point_value_t * now)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(now, RCUTILS_RET_INVALID_ARGUMENT);
  FILETIME ft;
  GetSystemTimePreciseAsFileTime(&ft);
  LARGE_INTEGER li;
  li.LowPart = ft.dwLowDateTime;
  li.HighPart = ft.dwHighDateTime;
  // Adjust for January 1st, 1970, see:
  //   https://support.microsoft.com/en-us/topic/bf03df72-96e4-59f3-1d02-b6781002dc7f
  li.QuadPart -= 116444736000000000;
  // Convert to nanoseconds from 100's of nanoseconds.
  *now = li.QuadPart * 100;
  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_steady_time_now(rcutils_time_point_value_t * now)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(now, RCUTILS_RET_INVALID_ARGUMENT);
  LARGE_INTEGER cpu_frequency, performance_count;
  // These should not ever fail since XP is already end of life:
  // From https://msdn.microsoft.com/en-us/library/windows/desktop/ms644905(v=vs.85).aspx and
  //      https://msdn.microsoft.com/en-us/library/windows/desktop/ms644904(v=vs.85).aspx:
  // "On systems that run Windows XP or later, the function will always succeed and will
  //  thus never return zero."
  QueryPerformanceFrequency(&cpu_frequency);
  QueryPerformanceCounter(&performance_count);
  // Calculate nanoseconds and seconds separately because
  // otherwise overflow can happen in intermediate calculations
  // This conversion will overflow if the PC runs >292 years non-stop
  const rcutils_time_point_value_t whole_seconds =
    performance_count.QuadPart / cpu_frequency.QuadPart;
  const rcutils_time_point_value_t remainder_count =
    performance_count.QuadPart % cpu_frequency.QuadPart;
  const rcutils_time_point_value_t remainder_ns =
    RCUTILS_S_TO_NS(remainder_count) / cpu_frequency.QuadPart;
  const rcutils_time_point_value_t total_ns =
    RCUTILS_S_TO_NS(whole_seconds) + remainder_ns;
  *now = total_ns;
  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_raw_steady_time_now(rcutils_time_point_value_t * now)
{
  // On Windows, there is no difference between steady and raw steady time.
  // The QueryPerformanceCounter function provides a high-resolution timer
  // that is not affected by system clock changes.
  return rcutils_steady_time_now(now);
}

rcutils_uint8_array_t
rcutils_get_zero_initialized_uint8_array(void)
{
  static rcutils_uint8_array_t uint8_array = {0};
  return uint8_array;
}

rcutils_ret_t
rcutils_uint8_array_init(
  rcutils_uint8_array_t * uint8_array,
  size_t buffer_capacity,
  const rcutils_allocator_t * allocator)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(uint8_array, RCUTILS_RET_INVALID_ARGUMENT);
  RCUTILS_CHECK_ALLOCATOR(allocator, return RCUTILS_RET_INVALID_ARGUMENT);

  uint8_array->buffer_length = 0lu;
  uint8_array->buffer_capacity = buffer_capacity;
  uint8_array->allocator = *allocator;

  if (buffer_capacity > 0lu) {
    if (buffer_capacity >= SIZE_MAX) {
      RCUTILS_SET_ERROR_MSG("requested capacity for uint8_array too large");
      uint8_array->buffer_capacity = 0lu;
      uint8_array->buffer_length = 0lu;
      return RCUTILS_RET_BAD_ALLOC;
    }
    uint8_array->buffer = (uint8_t *)allocator->allocate(
      buffer_capacity * sizeof(uint8_t), allocator->state);
    RCUTILS_CHECK_FOR_NULL_WITH_MSG(
      uint8_array->buffer,
      "failed to allocate memory for uint8 array",
      uint8_array->buffer_capacity = 0lu;
      uint8_array->buffer_length = 0lu;
      return RCUTILS_RET_BAD_ALLOC);
  }

  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_uint8_array_fini(rcutils_uint8_array_t * uint8_array)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(uint8_array, RCUTILS_RET_INVALID_ARGUMENT);

  rcutils_allocator_t * allocator = &uint8_array->allocator;
  RCUTILS_CHECK_ALLOCATOR(allocator, return RCUTILS_RET_INVALID_ARGUMENT);

  allocator->deallocate(uint8_array->buffer, allocator->state);
  uint8_array->buffer = NULL;
  uint8_array->buffer_length = 0lu;
  uint8_array->buffer_capacity = 0lu;

  return RCUTILS_RET_OK;
}

rcutils_ret_t
rcutils_uint8_array_resize(rcutils_uint8_array_t * uint8_array, size_t new_size)
{
  RCUTILS_CHECK_ARGUMENT_FOR_NULL(uint8_array, RCUTILS_RET_INVALID_ARGUMENT);

  if (0lu == new_size) {
    RCUTILS_SET_ERROR_MSG("new size of uint8_array has to be greater than zero");
    return RCUTILS_RET_INVALID_ARGUMENT;
  }

  rcutils_allocator_t * allocator = &uint8_array->allocator;
  RCUTILS_CHECK_ALLOCATOR(allocator, return RCUTILS_RET_INVALID_ARGUMENT);

  if (new_size == uint8_array->buffer_capacity) {
    // nothing to do here
    return RCUTILS_RET_OK;
  }
  if (new_size >= SIZE_MAX) {
    RCUTILS_SET_ERROR_MSG("requested size for uint8_array too large");
    return RCUTILS_RET_BAD_ALLOC;
  }

  uint8_array->buffer = rcutils_reallocf(
    uint8_array->buffer, new_size * sizeof(uint8_t), allocator);
  RCUTILS_CHECK_FOR_NULL_WITH_MSG(
    uint8_array->buffer,
    "failed to reallocate memory for uint8 array",
    uint8_array->buffer_capacity = 0lu;
    uint8_array->buffer_length = 0lu;
    return RCUTILS_RET_BAD_ALLOC);

  uint8_array->buffer_capacity = new_size;
  if (new_size < uint8_array->buffer_length) {
    uint8_array->buffer_length = new_size;
  }

  return RCUTILS_RET_OK;
}

